    def subscribe(
        self,
        callback: Callable[[Scenario, Job], None],
        params: Optional[List[Any]] = None,
    ):
        """Subscribe a function to be called on `Job^` status change.

        The subscription is applied to all jobs created from the scenario's execution.

        Parameters:
            callback (Callable[[Scenario^, Job^], None]): The callable function to be called
                on status change.
            params (Optional[List[Any]]): The parameters to be passed to the _callback_.

        Note:
            Notification will be available only for jobs created after this subscription.
        """
        from ... import core as tp

        return tp.subscribe_scenario(callback, params, self)

    def unsubscribe(self, callback: Callable[[Scenario, Job], None], params: Optional[List[Any]] = None):
        """Unsubscribe a function that is called when the status of a `Job^` changes.

        Parameters:
            callback (Callable[[Scenario^, Job^], None]): The callable function to unsubscribe.
            params (Optional[List[Any]]): The parameters to be passed to the _callback_.

        Note:
            The function will continue to be called for ongoing jobs.
        """
        from ... import core as tp

        return tp.unsubscribe_scenario(callback, params, self)

    def submit(
        self,
        callbacks: Optional[List[Callable]] = None,
        force: bool = False,
        wait: bool = False,
        timeout: Optional[Union[float, int]] = None,
        **properties,
    ) -> Submission:
        """Submit this scenario for execution.

        All the `Task^`s of the scenario will be submitted for execution.

        Parameters:
            callbacks (List[Callable]): The list of callable functions to be called on status
                change.
            force (bool): Force execution even if the data nodes are in cache.
            wait (bool): Wait for the orchestrated jobs created from the scenario submission to be finished in
                asynchronous mode.
            timeout (Union[float, int]): The optional maximum number of seconds to wait for the jobs to be finished
                before returning.
            **properties (dict[str, any]): A keyworded variable length list of additional arguments.
        Returns:
            A `Submission^` containing the information of the submission.
        """
        from ._scenario_manager_factory import _ScenarioManagerFactory

        return _ScenarioManagerFactory._build_manager()._submit(self, callbacks, force, wait, timeout, **properties)

    def export(
        self,
        folder_path: Union[str, pathlib.Path],
    ):
        """Export all related entities of this scenario to a folder.

        Parameters:
            folder_path (Union[str, pathlib.Path]): The folder path to export the scenario to.
        """
        from ... import core as tp

        return tp.export_scenario(self.id, folder_path)

    def set_primary(self):
        """Promote the scenario as the primary scenario of its cycle.

        If the cycle already has a primary scenario, it will be demoted, and it will no longer
        be primary for the cycle.
        """
        from ... import core as tp

        return tp.set_primary(self)

    def add_tag(self, tag: str):
        """Add a tag to this scenario.

        If the scenario's cycle already have another scenario tagged with _tag_ the other
        scenario will be untagged.

        Parameters:
            tag (str): The tag to add to this scenario.
        """
        from ... import core as tp

        return tp.tag(self, tag)

    def remove_tag(self, tag: str):
        """Remove a tag from this scenario.

        Parameters:
            tag (str): The tag to remove from the set of the scenario's tags.
        """
        from ... import core as tp

        return tp.untag(self, tag)

    def is_deletable(self) -> bool:
        """Indicate if the scenario can be deleted.

        Returns:
            True if the scenario can be deleted. False otherwise.
        """
        from ... import core as tp

        return tp.is_deletable(self)

    def get_label(self) -> str:
        """Returns the scenario simple label prefixed by its owner label.

        Returns:
            The label of the scenario as a string.
        """
        return self._get_label()

    def get_simple_label(self) -> str:
        """Returns the scenario simple label.

        Returns:
            The simple label of the scenario as a string.
        """
        return self._get_simple_label()

    def _is_consistent(self) -> bool:
        dag = self._build_dag()
        if dag.number_of_nodes() == 0:
            return True
        if not nx.is_directed_acyclic_graph(dag):
            return False
        for left_node, right_node in dag.edges:
            if (isinstance(left_node, DataNode) and isinstance(right_node, Task)) or (
                isinstance(left_node, Task) and isinstance(right_node, DataNode)
            ):
                continue
            return False
        return True

def _get_all_by_cycle(cls, cycle: Cycle) -> List[Scenario]:
    filters = cls._build_filters_with_version("all")

    if not filters:
        filters = [{}]
    for fil in filters:
        fil.update({"cycle": cycle.id})
    return cls._get_all_by(filters)

def _get_all(cls, version_number: Optional[str] = None) -> List[Scenario]:
    """
    Returns all entities.
    """
    filters = cls._build_filters_with_version(version_number)
    return cls._repository._load_all(filters)

def _set_primary(cls, scenario: Scenario):
    if not scenario.cycle:
        raise DoesNotBelongToACycle(
            f"Can't set scenario {scenario.id} to primary because it doesn't belong to a cycle."
        )

    primary_scenario = cls._get_primary(scenario.cycle)
    # To prevent SAME scenario updating out of Context Manager
    if primary_scenario and primary_scenario != scenario:
        primary_scenario.is_primary = False  # type: ignore
    scenario.is_primary = True  # type: ignore

def _get_primary(cls, cycle: Cycle) -> Optional[Scenario]:
    scenarios = cls._get_all_by_cycle(cycle)
    for scenario in scenarios:
        if scenario.is_primary:
            return scenario
    return None

def _get_primary_scenarios(
    cls, sorted: Optional[bool] = False, sort_key: Optional[Literal["name", "id", "creation_date", "tags"]] = "name"
) -> List[Scenario]:
    scenarios = [scenario for scenario in cls._get_all() if scenario.is_primary]
    if sorted:
        if sort_key in ["name", "id", "creation_date", "tags"]:
            scenarios.sort(key=lambda x: getattr(x, sort_key))
        else:
            scenarios.sort(key=lambda x: x.name)
    return scenarios

def _create(
    cls,
    config: ScenarioConfig,
    creation_date: Optional[datetime.datetime] = None,
    name: Optional[str] = None,
) -> Scenario:
    _task_manager = _TaskManagerFactory._build_manager()
    _data_manager = _DataManagerFactory._build_manager()

    scenario_id = Scenario._new_id(str(config.id))
    cycle = (
        _CycleManagerFactory._build_manager()._get_or_create(config.frequency, creation_date)
        if config.frequency
        else None
    )
    cycle_id = cycle.id if cycle else None
    tasks = (
        _task_manager._bulk_get_or_create(config.task_configs, cycle_id, scenario_id) if config.task_configs else []
    )
    additional_data_nodes = (
        _data_manager._bulk_get_or_create(config.additional_data_node_configs, cycle_id, scenario_id)
        if config.additional_data_node_configs
        else {}
    )

    sequences = {}
    tasks_and_config_id_maps = {task.config_id: task for task in tasks}
    for sequence_name, sequence_task_configs in config.sequences.items():
        sequence_tasks = []
        non_existing_sequence_task_config_in_scenario_config = set()
        for sequence_task_config in sequence_task_configs:
            if task := tasks_and_config_id_maps.get(sequence_task_config.id):
                sequence_tasks.append(task)
            else:
                non_existing_sequence_task_config_in_scenario_config.add(sequence_task_config.id)
        if non_existing_sequence_task_config_in_scenario_config:
            raise SequenceTaskConfigDoesNotExistInSameScenarioConfig(
                list(non_existing_sequence_task_config_in_scenario_config), sequence_name, str(config.id)
            )
        sequences[sequence_name] = {Scenario._SEQUENCE_TASKS_KEY: sequence_tasks}

    is_primary_scenario = len(cls._get_all_by_cycle(cycle)) == 0 if cycle else False
    props = config._properties.copy()
    if name:
        props["name"] = name
    version = cls._get_latest_version()

    scenario = Scenario(
        config_id=str(config.id),
        tasks=set(tasks),
        properties=props,
        additional_data_nodes=set(additional_data_nodes.values()),
        scenario_id=scenario_id,
        creation_date=creation_date,
        is_primary=is_primary_scenario,
        cycle=cycle,
        version=version,
        sequences=sequences,
    )

    for task in tasks:
        if scenario_id not in task._parent_ids:
            task._parent_ids.update([scenario_id])
            _task_manager._set(task)

    for dn in additional_data_nodes.values():
        if scenario_id not in dn._parent_ids:
            dn._parent_ids.update([scenario_id])
            _data_manager._set(dn)

    cls._set(scenario)

    if not scenario._is_consistent():
        raise InvalidSscenario(scenario.id)

    actual_sequences = scenario._get_sequences()
    for sequence_name in sequences.keys():
        if not actual_sequences[sequence_name]._is_consistent():
            raise InvalidSequence(actual_sequences[sequence_name].id)
        Notifier.publish(_make_event(actual_sequences[sequence_name], EventOperation.CREATION))

    Notifier.publish(_make_event(scenario, EventOperation.CREATION))
    return scenario

def _set_primary(cls, scenario: Scenario):
    if not scenario.cycle:
        raise DoesNotBelongToACycle(
            f"Can't set scenario {scenario.id} to primary because it doesn't belong to a cycle."
        )

    primary_scenario = cls._get_primary(scenario.cycle)
    # To prevent SAME scenario updating out of Context Manager
    if primary_scenario and primary_scenario != scenario:
        primary_scenario.is_primary = False  # type: ignore
    scenario.is_primary = True  # type: ignore

