def _execute_job(self, job: Job):
    if job.force or self._needs_to_run(job.task):
        if job.force:
            self._logger.info(f"job {job.id} is forced to be executed.")
        job.running()
        self._dispatch(job)
    else:
        job._unlock_edit_on_outputs()
        job.skipped()
        self._logger.info(f"job {job.id} is skipped.")

