def metrics_to_scalars(metrics: dict) -> dict:
    """ Recursively walk through a dictionary of metrics and convert single-item tensors to scalar values. """

    # TODO: this is duplicated in MetricsHolder. should be unified
    new_metrics = {}
    for k, v in metrics.items():
        if isinstance(v, torch.Tensor):
            if v.numel() != 1:
                raise MisconfigurationException(
                    f"The metric `{k}` does not contain a single element"
                    f" thus it cannot be converted to float. Found `{v}`"
                )
            v = v.item()

        if isinstance(v, dict):
            v = metrics_to_scalars(v)

        new_metrics[k] = v

    return new_metrics

def on_evaluation_epoch_end(self, outputs: Union[List[List[Dict]], List[Dict]]) -> None:
    model_ref = self.trainer.lightning_module
    hook_name = "on_test_epoch_end" if self.trainer.testing else "on_validation_epoch_end"

    self.trainer._reset_result_and_set_hook_fx_name(hook_name)

    with self.trainer.profiler.profile(hook_name):

        if hasattr(self.trainer, hook_name):
            on_evaluation_epoch_end_hook = getattr(self.trainer, hook_name)
            on_evaluation_epoch_end_hook(outputs)

        if is_overridden(hook_name, model_ref):
            model_hook_fx = getattr(model_ref, hook_name)
            if is_param_in_hook_signature(model_hook_fx, "outputs"):
                model_hook_fx(outputs)
            else:
                self.warning_cache.warn(
                    f"`ModelHooks.{hook_name}` signature has changed in v1.3. `outputs` parameter has been added."
                    " Support for the old signature will be removed in v1.5", DeprecationWarning
                )
                model_hook_fx()

    self.trainer._cache_logged_metrics()

    self.trainer.call_hook('on_epoch_end')

def _reset_result_and_set_hook_fx_name(self, hook_name: str) -> bool:
    # on_before_zero_grad is called within training_step
    if "batch_start" in hook_name or hook_name in ("on_before_zero_grad", "on_after_backward"):
        return True
    model_ref = self.lightning_module
    if model_ref is not None:
        # used to track current hook name called
        model_ref._results = Result()
        model_ref._current_hook_fx_name = hook_name
    return False

def is_param_in_hook_signature(hook_fx: Callable, param: str) -> bool:
    hook_params = list(inspect.signature(hook_fx).parameters)
    if "args" in hook_params or param in hook_params:
        return True
    return False

