def get_query(self, entities=[], entity_name="events") -> Tuple[str, Dict[str, Any]]:
    _fields = (
        f"{self.EVENT_TABLE_ALIAS}.event as event, {self.EVENT_TABLE_ALIAS}.team_id as team_id, {self.EVENT_TABLE_ALIAS}.distinct_id as distinct_id, {self.EVENT_TABLE_ALIAS}.timestamp as timestamp, {self.EVENT_TABLE_ALIAS}.properties as properties, {self.EVENT_TABLE_ALIAS}.elements_chain as elements_chain"
        + (f", {self.DISTINCT_ID_TABLE_ALIAS}.person_id as person_id" if self._should_join_distinct_ids else "")
        + (f", {self.PERSON_TABLE_ALIAS}.person_props as person_props" if self._should_join_persons else "")
    )

    date_query, date_params = self._get_date_filter()
    self.params.update(date_params)

    prop_filters = self._filter.properties
    prop_query, prop_params = self._get_props(prop_filters)
    self.params.update(prop_params)

    entity_query, entity_params = self._get_entity_query(entities, entity_name)
    self.params.update(entity_params)

    query = f"""
        SELECT {_fields} FROM events {self.EVENT_TABLE_ALIAS}
        {self._get_disintct_id_query()}
        {self._get_person_query()}
        WHERE team_id = %(team_id)s
        {entity_query}
        {date_query}
        {prop_query}
    """

    return query, self.params

def _get_entity_query(self, entities=[], entity_name="events") -> Tuple[str, Dict[str, Any]]:
    events = []
    entities_to_use = self._filter.entities
    if len(entities) > 0:
        entities_to_use = entities
    for entity in entities_to_use:
        if entity.type == TREND_FILTER_TYPE_ACTIONS:
            action = Action.objects.get(pk=entity.id)
            for action_step in action.steps.all():
                events.append(action_step.event)
        else:
            events.append(entity.id)

    return f"AND event IN %({entity_name})s", {entity_name: events}

def _create_person(**kwargs):
    person = Person.objects.create(**kwargs)
    return Person(id=person.uuid, uuid=person.uuid)

class Person(models.Model):
    @property
    def distinct_ids(self) -> List[str]:
        if hasattr(self, "distinct_ids_cache"):
            return [id.distinct_id for id in self.distinct_ids_cache]  # type: ignore
        return [
            id[0]
            for id in PersonDistinctId.objects.filter(person=self, team_id=self.team_id)
            .order_by("id")
            .values_list("distinct_id")
        ]

    def add_distinct_id(self, distinct_id: str) -> None:
        PersonDistinctId.objects.create(person=self, distinct_id=distinct_id, team_id=self.team_id)

    def add_distinct_ids(self, distinct_ids: List[str]) -> None:
        for distinct_id in distinct_ids:
            self.add_distinct_id(distinct_id)

    def merge_people(self, people_to_merge: List["Person"]):
        CohortPeople = apps.get_model(app_label="posthog", model_name="CohortPeople")

        first_seen = self.created_at

        # merge the properties
        for other_person in people_to_merge:
            self.properties = {**other_person.properties, **self.properties}
            if other_person.created_at < first_seen:
                # Keep the oldest created_at (i.e. the first time we've seen this person)
                first_seen = other_person.created_at
        self.created_at = first_seen
        self.save()

        # merge the distinct_ids
        for other_person in people_to_merge:
            other_person_distinct_ids = PersonDistinctId.objects.filter(person=other_person, team_id=self.team_id)
            for person_distinct_id in other_person_distinct_ids:
                person_distinct_id.person = self
                person_distinct_id.save()

            other_person_cohort_ids = CohortPeople.objects.filter(person=other_person)
            for person_cohort_id in other_person_cohort_ids:
                person_cohort_id.person = self
                person_cohort_id.save()

            other_person.delete()

    objects = PersonManager()
    created_at: models.DateTimeField = models.DateTimeField(auto_now_add=True, blank=True)
    team: models.ForeignKey = models.ForeignKey("Team", on_delete=models.CASCADE)
    properties: models.JSONField = models.JSONField(default=dict)
    is_user: models.ForeignKey = models.ForeignKey("User", on_delete=models.CASCADE, null=True, blank=True)
    is_identified: models.BooleanField = models.BooleanField(default=False)
    uuid = models.UUIDField(db_index=True, default=UUIDT, editable=False)

    # Has an index on properties -> email, built concurrently
    # See migration 0121

    @staticmethod
    def get_distinct_ids_and_email_by_ids(person_ids, team_id):
        decorated = []
        for person_id in person_ids:
            distinct_ids, email = Person.get_distinct_ids_and_email_by_id(person_id, team_id)
            decorated.append({"distinct_ids": distinct_ids, "email": email})
        return decorated

    @staticmethod
    def get_distinct_ids_and_email_by_id(person_id, team_id):
        person = Person.objects.get(uuid=person_id)
        distinct_ids = PersonDistinctId.objects.filter(person_id=person.id, team_id=team_id)
        flat_distinct_ids = [row.distinct_id for row in distinct_ids]
        email = person.properties.get("email", "")
        return flat_distinct_ids, email

