    with transaction.atomic():
        if not kwargs.get("distinct_ids"):
            return super().create(*args, **kwargs)
        distinct_ids = kwargs.pop("distinct_ids")
        person = super().create(*args, **kwargs)
        person.add_distinct_ids(distinct_ids)
        return person

