def assert_max_deps(x, n, eq=True):
    dependencies, dependents = get_deps(x.dask)
    if eq:
        assert max(map(len, dependencies.values())) == n
    else:
        assert max(map(len, dependencies.values())) <= n

def _fillna_groups(groups, axis, **kwargs):
    if axis == 0:
        return groups.fillna(axis=axis, **kwargs)
    else:
        return groups.drop(columns=groups.columns[0], axis=1).fillna(
            axis=axis, **kwargs
        )

def fillna(self, value=None, method=None, limit=None, axis=None):
    if not np.isscalar(value) and value is not None:
        raise NotImplementedError(
            "groupby-fillna with value=dict/Series/DataFrame is currently not supported"
        )
    axis = DataFrame._validate_axis(axis)
    if value is not None or axis == 0:
        meta = self._meta_nonempty.transform(
            _fillna_groups, value=value, method=method, limit=limit, axis=0
        )
        return self.transform(
            _fillna_groups,
            value=value,
            method=method,
            limit=limit,
            axis=0,
            meta=meta,
        )
    else:
        meta = self._meta_nonempty.apply(
            _fillna_groups, value=value, method=method, limit=limit, axis=1
        )
        return self.apply(
            _fillna_groups,
            value=value,
            method=method,
            limit=limit,
            axis=1,
            meta=meta,
        )

def drop(self, labels=None, axis=0, columns=None, errors="raise"):
    axis = self._validate_axis(axis)
    if axis == 0 and columns is not None:
        # Columns must be specified if axis==0
        return self.map_partitions(drop_by_shallow_copy, columns, errors=errors)
    elif axis == 1:
        return self.map_partitions(drop_by_shallow_copy, labels, errors=errors)
    raise NotImplementedError(
        "Drop currently only works for axis=1 or when columns is not None"
    )

def assert_eq(
    a,
    b,
    check_names=True,
    check_dtype=True,
    check_divisions=True,
    check_index=True,
    scheduler="sync",
    **kwargs,
):
    if check_divisions:
        assert_divisions(a, scheduler=scheduler)
        assert_divisions(b, scheduler=scheduler)
        if hasattr(a, "divisions") and hasattr(b, "divisions"):
            at = type(np.asarray(a.divisions).tolist()[0])  # numpy to python
            bt = type(np.asarray(b.divisions).tolist()[0])  # scalar conversion
            assert at == bt, (at, bt)
    assert_sane_keynames(a)
    assert_sane_keynames(b)
    a = _check_dask(
        a, check_names=check_names, check_dtypes=check_dtype, scheduler=scheduler
    )
    b = _check_dask(
        b, check_names=check_names, check_dtypes=check_dtype, scheduler=scheduler
    )
    if hasattr(a, "to_pandas"):
        a = a.to_pandas()
    if hasattr(b, "to_pandas"):
        b = b.to_pandas()
    if isinstance(a, (pd.DataFrame, pd.Series)):
        a = _maybe_sort(a, check_index)
        b = _maybe_sort(b, check_index)
    if not check_index:
        a = a.reset_index(drop=True)
        b = b.reset_index(drop=True)
    if isinstance(a, pd.DataFrame):
        tm.assert_frame_equal(
            a, b, check_names=check_names, check_dtype=check_dtype, **kwargs
        )
    elif isinstance(a, pd.Series):
        tm.assert_series_equal(
            a, b, check_names=check_names, check_dtype=check_dtype, **kwargs
        )
    elif isinstance(a, pd.Index):
        tm.assert_index_equal(a, b, exact=check_dtype, **kwargs)
    else:
        if a == b:
            return True
        else:
            if np.isnan(a):
                assert np.isnan(b)
            else:
                assert np.allclose(a, b)
    return True

