class RollingGroupby(Rolling):
    def __init__(
        self,
        groupby,
        window=None,
        min_periods=None,
        center=False,
        win_type=None,
        axis=0,
    ):
        self._groupby_kwargs = groupby._groupby_kwargs
        self._groupby_slice = groupby._slice

        obj = groupby.obj
        if self._groupby_slice is not None:
            if isinstance(self._groupby_slice, str):
                sliced_plus = [self._groupby_slice]
            else:
                sliced_plus = list(self._groupby_slice)
            if isinstance(groupby.by, str):
                sliced_plus.append(groupby.by)
            else:
                sliced_plus.extend(groupby.by)
            obj = obj[sliced_plus]

        super().__init__(
            obj,
            window=window,
            min_periods=min_periods,
            center=center,
            win_type=win_type,
            axis=axis,
        )

    @staticmethod
    def pandas_rolling_method(
        df,
        rolling_kwargs,
        name,
        *args,
        groupby_kwargs=None,
        groupby_slice=None,
        **kwargs,
    ):
        groupby = df.groupby(**groupby_kwargs)
        if groupby_slice:
            groupby = groupby[groupby_slice]
        rolling = groupby.rolling(**rolling_kwargs)
        return getattr(rolling, name)(*args, **kwargs).sort_index(level=-1)

    def _call_method(self, method_name, *args, **kwargs):
        return super()._call_method(
            method_name,
            *args,
            groupby_kwargs=self._groupby_kwargs,
            groupby_slice=self._groupby_slice,
            **kwargs,
        )

def _fillna_groups(groups, axis, **kwargs):
    if axis == 0:
        return groups.fillna(axis=axis, **kwargs)
    else:
        return groups.drop(columns=groups.columns[0], axis=1).fillna(
            axis=axis, **kwargs
        )

def fillna(self, value=None, method=None, limit=None, axis=None):
    if not np.isscalar(value) and value is not None:
        raise NotImplementedError(
            "groupby-fillna with value=dict/Series/DataFrame is currently not supported"
        )
    axis = DataFrame._validate_axis(axis)
    if value is not None or axis == 0:
        meta = self._meta_nonempty.transform(
            _fillna_groups, value=value, method=method, limit=limit, axis=0
        )
        return self.transform(
            _fillna_groups,
            value=value,
            method=method,
            limit=limit,
            axis=0,
            meta=meta,
        )
    else:
        meta = self._meta_nonempty.apply(
            _fillna_groups, value=value, method=method, limit=limit, axis=1
        )
        return self.apply(
            _fillna_groups,
            value=value,
            method=method,
            limit=limit,
            axis=1,
            meta=meta,
        )

def _validate_axis(cls, axis=0):
    if axis not in (0, 1, "index", "columns", None):
        raise ValueError(f"No axis named {axis}")
    # convert to numeric axis
    return {None: 0, "index": 0, "columns": 1}.get(axis, axis)

