def groupby(
    self, by=None, group_keys=True, sort=None, observed=None, dropna=None, **kwargs
):
    from dask.dataframe.groupby import DataFrameGroupBy

    return DataFrameGroupBy(
        self,
        by=by,
        group_keys=group_keys,
        sort=sort,
        observed=observed,
