def resolve_ref(
    self,
    target_model_name: str,
    target_model_package: Optional[str],
    current_project: str,
    node_package: str,
) -> MaybeNonSource:

    node: Optional[ManifestNode] = None
    disabled: Optional[List[ManifestNode]] = None

    candidates = _search_packages(current_project, node_package, target_model_package)
    for pkg in candidates:
        node = self.ref_lookup.find(target_model_name, pkg, self)

        if node is not None and node.config.enabled:
            return node

        # it's possible that the node is disabled
        if disabled is None:
            disabled = self.disabled_lookup.find(target_model_name, pkg)

    if disabled:
        return Disabled(disabled[0])
    return None

def resolve_source(
    self,
    target_source_name: str,
    target_table_name: str,
    current_project: str,
    node_package: str,
) -> MaybeParsedSource:
    search_name = f"{target_source_name}.{target_table_name}"
    candidates = _search_packages(current_project, node_package)

    source: Optional[ParsedSourceDefinition] = None
    disabled: Optional[List[ParsedSourceDefinition]] = None

    for pkg in candidates:
        source = self.source_lookup.find(search_name, pkg, self)
        if source is not None and source.config.enabled:
            return source

        if disabled is None:
            disabled = self.disabled_lookup.find(
                f"{target_source_name}.{target_table_name}", pkg
            )

    if disabled:
        return Disabled(disabled[0])
    return None

def resolve(self, source_name: str, table_name: str):
    target_source = self.manifest.resolve_source(
        source_name,
        table_name,
        self.current_project,
        self.model.package_name,
    )

    if target_source is None or isinstance(target_source, Disabled):
        source_target_not_found(
            self.model,
            source_name,
            table_name,
        )
    return self.Relation.create_from_source(target_source)

def source_target_not_found(
    model, target_name: str, target_table_name: str, disabled: Optional[bool] = None
) -> NoReturn:
    msg = get_source_not_found_or_disabled_msg(model, target_name, target_table_name, disabled)
    raise_compiler_error(msg, model)

def create_from_source(self, *args, **kwargs):
    # bypass our create when creating from source so as not to mess up
    # the source quoting
    return self._relation_type.create_from_source(*args, **kwargs)

def resolve(self, name: str, package: Optional[str] = None) -> MetricReference:
    self.model.metrics.append(self._repack_args(name, package))

    return MetricReference(name, package)

class MetricReference(object):
    def __init__(self, metric_name, package_name=None):
        self.metric_name = metric_name
        self.package_name = package_name

def resolve(self, target_name: str, target_package: Optional[str] = None) -> MetricReference:
    target_metric = self.manifest.resolve_metric(
        target_name,
        target_package,
        self.current_project,
        self.model.package_name,
    )

    if target_metric is None or isinstance(target_metric, Disabled):
        # TODO : Use a different exception!!
        ref_target_not_found(
            self.model,
            target_name,
            target_package,
            disabled=isinstance(target_metric, Disabled),
        )

    return ResolvedMetricReference(target_metric)

class ResolvedMetricReference(MetricReference):
    """
    Simple proxy over a ParsedMetric which delegates property
    lookups to the underlying node. Also adds helper functions
    for working with metrics (ie. __str__ and templating functions)
    """
    def __init__(self, node):
        super().__init__(node.name, node.package_name)
        self.node = node

    def __getattr__(self, key):
        return getattr(self.node, key)

    @property
    def is_derived(self):
        return self.node.is_derived

    def qualify(self, namespace):
        return f'{namespace}.{self.metric_name}'

    def __str__(self):
        return self.node.name

