                                "genre": ["economy", "politics"],
                                "publisher": "nytimes"
                            }
                        }
                        ```

                        To use the same logical operator multiple times on the same level, logical operators take
                        optionally a list of dictionaries as value.

                        __Example__:

                        ```python
                        filters = {
                            "$or": [
                                {
                                    "$and": {
                                        "Type": "News Paper",
                                        "Date": {
                                            "$lt": "2019-01-01"
                                        }
                                    }
                                },
                                {
                                    "$and": {
                                        "Type": "Blog Post",
                                        "Date": {
                                            "$gte": "2019-01-01"
                                        }
                                    }
                                }
                            ]
                        }
                        ```
    :param top_k: How many documents to return per query.
    :param index: The name of the index in the DocumentStore from which to retrieve documents
    :param batch_size: Number of queries to embed at a time.
    :param scale_score: Whether to scale the similarity score to the unit interval (range of [0,1]).
                        If true similarity scores (e.g. cosine or dot_product) which naturally have a different
                        value range will be scaled to a range of [0,1], where 1 means extremely relevant.
                        Otherwise raw similarity scores (e.g. cosine or dot_product) will be used.
    :param document_store: the docstore to use for retrieval. If `None`, the one given in the `__init__` is used instead.
    """
    document_store = document_store or self.document_store
    if document_store is None:
        raise ValueError(
            "This Retriever was not initialized with a Document Store. Provide one to the retrieve() method."
        )

    if top_k is None:
        top_k = self.top_k

    if batch_size is None:
        batch_size = self.batch_size

    if isinstance(filters, list):
        if len(filters) != len(queries):
            raise HaystackError(
                "Number of filters does not match number of queries. Please provide as many filters"
                " as queries or a single filter that will be applied to each query."
            )
    else:
        filters = [filters] * len(queries) if filters is not None else [{}] * len(queries)

    if index is None:
        index = document_store.index
    if scale_score is None:
        scale_score = self.scale_score

    query_embs: List[np.ndarray] = []
    for batch in self._get_batches(queries=queries, batch_size=batch_size):
        query_embs.extend(self.embed_queries(queries=batch))
    documents = document_store.query_by_embedding_batch(
        query_embs=query_embs, top_k=top_k, filters=filters, index=index, headers=headers, scale_score=scale_score
    )

    return documents

def _get_batches(queries: List[str], batch_size: Optional[int]) -> Iterator[List[str]]:
    if batch_size is None:
        yield queries
        return
    else:
        for index in range(0, len(queries), batch_size):
            yield queries[index : index + batch_size]

class HaystackError(Exception):
    """
    Any error generated by Haystack.

    This error wraps its source transparently in such a way that its attributes
    can be accessed directly: for example, if the original error has a `message` attribute,
    `HaystackError.message` will exist and have the expected content.
    If send_message_in_event is set to True (default), the message will be sent as part of a telemetry event reporting the error.
    The messages of errors that might contain user-specific information will not be sent, e.g., DocumentStoreError or OpenAIError.
    """

    def __init__(
        self, message: Optional[str] = None, docs_link: Optional[str] = None, send_message_in_event: bool = True
    ):
        payload = {"message": message} if send_message_in_event else {}
        send_custom_event(event=f"{type(self).__name__} raised", payload=payload)
        super().__init__()
        if message:
            self.message = message
        self.docs_link = None

    def __getattr__(self, attr):
        # If self.__cause__ is None, it will raise the expected AttributeError
        getattr(self.__cause__, attr)

    def __str__(self):
        if self.docs_link:
            docs_message = f"\n\nCheck out the documentation at {self.docs_link}"
            return self.message + docs_message
        return self.message

    def __repr__(self):
        return str(self)

