    if index is None:
        index = self.index

    body = self._construct_query_body(
        query=query,
        filters=filters,
        top_k=top_k,
        custom_query=custom_query,
        all_terms_must_match=all_terms_must_match,
    )

    logger.debug("Retriever query: %s", body)
    result = self.client.search(index=index, body=body, headers=headers)["hits"]["hits"]

    documents = [
        self._convert_es_hit_to_document(hit, return_embedding=self.return_embedding, scale_score=scale_score)
        for hit in result
    ]
    return documents

def _convert_es_hit_to_document(
    self, hit: dict, return_embedding: bool, adapt_score_for_embedding: bool = False, scale_score: bool = True
) -> Document:
    # We put all additional data of the doc into meta_data and return it in the API
    try:
        meta_data = {
            k: v
            for k, v in hit["_source"].items()
            if k not in (self.content_field, "content_type", self.embedding_field)
        }
        name = meta_data.pop(self.name_field, None)
        if name:
            meta_data["name"] = name

        if "highlight" in hit:
            meta_data["highlighted"] = hit["highlight"]

        score = hit["_score"]
        if score:
            if adapt_score_for_embedding:
                score = self._get_raw_similarity_score(score)

            if scale_score:
                if adapt_score_for_embedding:
                    score = self.scale_to_unit_interval(score, self.similarity)
                else:
                    score = float(expit(np.asarray(score / 8)))  # scaling probability from TFIDF/BM25

        embedding = None
        if return_embedding:
            embedding_list = hit["_source"].get(self.embedding_field)
            if embedding_list:
                embedding = np.asarray(embedding_list, dtype=np.float32)

        doc_dict = {
            "id": hit["_id"],
            "content": hit["_source"].get(self.content_field),
            "content_type": hit["_source"].get("content_type", None),
            "meta": meta_data,
            "score": score,
            "embedding": embedding,
        }
        document = Document.from_dict(doc_dict)
    except (KeyError, ValidationError) as e:
        raise DocumentStoreError(
            f"Failed to create documents from the content of the document store. Make sure the index you specified contains documents."
        ) from e
    return document

def from_dict(
    cls, dict: Dict[str, Any], field_map: Dict[str, Any] = {}, id_hash_keys: Optional[List[str]] = None
) -> Document:
    """
    Create Document from dict. An optional field_map can be supplied to adjust for custom names of the keys in the
    input dict. This way you can work with standardized Document objects in Haystack, but adjust the format that
    they are serialized / stored in other places (e.g. elasticsearch)
    Example:

    ```python
    my_dict = {"custom_content_field": "some text", content_type": "text"}
    Document.from_dict(my_dict, field_map={"custom_content_field": "content"})
    ```

    :param field_map: Dict with keys being the custom target keys and values being the standard Document attributes
    :return: dict with content of the Document
    """

    _doc = dict.copy()
    init_args = ["content", "content_type", "id", "score", "question", "meta", "embedding"]
    if "meta" not in _doc.keys():
        _doc["meta"] = {}
    # copy additional fields into "meta"
    for k, v in _doc.items():
        # Exclude internal fields (Pydantic, ...) fields from the conversion process
        if k.startswith("__"):
            continue
        if k not in init_args and k not in field_map:
            _doc["meta"][k] = v
    # remove additional fields from top level
    _new_doc = {}
    for k, v in _doc.items():
        if k in init_args:
            _new_doc[k] = v
        elif k in field_map:
            k = field_map[k]
            _new_doc[k] = v

    if _doc.get("id") is None:
        _new_doc["id_hash_keys"] = id_hash_keys

    # Convert list of rows to pd.DataFrame
    if _new_doc.get("content_type", None) == "table" and isinstance(_new_doc["content"], list):
        _new_doc["content"] = pd.DataFrame(columns=_new_doc["content"][0], data=_new_doc["content"][1:])

    return cls(**_new_doc)

def scale_to_unit_interval(self, score: float, similarity: Optional[str]) -> float:
    if similarity == "cosine":
        return (score + 1) / 2
    else:
        return float(expit(score / 100))

class DocumentStoreError(HaystackError):
    """Exception for issues that occur in a document store"""

    def __init__(self, message: Optional[str] = None, send_message_in_event: bool = False):
        super().__init__(message=message, send_message_in_event=send_message_in_event)

