    pb = tqdm(total=len(queries), disable=not self.progress_bar, desc="Querying")
    for batch, cur_filters in zip(batches, filters):
        context_docs: List[List[Document]] = [[] for _ in range(len(batch))]
        for it in range(self.num_iterations):
            texts = [self._merge_query_and_context(q, c) for q, c in zip(batch, context_docs)]
            query_embs = self.embed_queries(texts)
            cur_docs_batch = document_store.query_by_embedding_batch(
                query_embs=query_embs,
                top_k=top_k,
                filters=cur_filters,
                index=index,
                headers=headers,
                scale_score=scale_score,
            )
            if it < self.num_iterations - 1:
                # add doc with highest score to context
                for idx, cur_docs in enumerate(cur_docs_batch):
                    if len(cur_docs) > 0:
                        context_docs[idx].append(cur_docs[0])
            else:
                # documents in the last iteration are final results
                documents.extend(cur_docs_batch)
        pb.update(len(batch))
    pb.close()

    return documents

class HaystackError(Exception):
    """
    Any error generated by Haystack.

    This error wraps its source transparently in such a way that its attributes
    can be accessed directly: for example, if the original error has a `message` attribute,
    `HaystackError.message` will exist and have the expected content.
    If send_message_in_event is set to True (default), the message will be sent as part of a telemetry event reporting the error.
    The messages of errors that might contain user-specific information will not be sent, e.g., DocumentStoreError or OpenAIError.
    """

    def __init__(
        self, message: Optional[str] = None, docs_link: Optional[str] = None, send_message_in_event: bool = True
    ):
        payload = {"message": message} if send_message_in_event else {}
        send_custom_event(event=f"{type(self).__name__} raised", payload=payload)
        super().__init__()
        if message:
            self.message = message
        self.docs_link = None

    def __getattr__(self, attr):
        # If self.__cause__ is None, it will raise the expected AttributeError
        getattr(self.__cause__, attr)

    def __str__(self):
        if self.docs_link:
            docs_message = f"\n\nCheck out the documentation at {self.docs_link}"
            return self.message + docs_message
        return self.message

    def __repr__(self):
        return str(self)

def _get_batches(queries: List[str], batch_size: Optional[int]) -> Iterator[List[str]]:
    if batch_size is None:
        yield queries
        return
    else:
        for index in range(0, len(queries), batch_size):
            yield queries[index : index + batch_size]

