def __init__(self, group=None, target=None, name=None, args=(), kwargs={}, *, daemon=None):
    target = thread_wrapped_func(target)
    super().__init__(group, target, name, args, kwargs, daemon=daemon)

def __init__(self, group=None, target=None, name=None, args=(), kwargs={}, *, daemon=None):
    target = thread_wrapped_func(target)
