def get_interpretation_neighbors(self, x):
    leave_one_out_sets = []
    for choice in [value for _, value in self.choices]:
        leave_one_out_set = list(x)
        if choice in leave_one_out_set:
            leave_one_out_set.remove(choice)
        else:
