def zero_grad(self, set_to_none=True):
    """
    Set parameter gradients to zero. If set_to_none = True, gradient
    will be set to None to save memory.

    :param set_to_none: Whether set the gradient to None. Default value is True.
    :type set_to_none: bool
    """
    if self.mixed_precision_mixin is not None:
        self.mixed_precision_mixin.pre_zero_grad()
    for _, param_group in self._working_param_groups.items():
        for param in param_group:
            if set_to_none:
                param.grad = None
            else:
                if param.grad is not None:
                    param.grad.detach()
                    param.grad.zero_()
    self.zero_grad_stores()
    self.zero_bucket_stores()

def __gather(self, async_op: bool = False) -> Optional[dist.Work]:
    if not self.is_gathered:
        # sanity check
