        alloc_storage(self.cuda_global_chunk)
        assert self.cuda_global_chunk.is_contiguous()
        if self.fp8_communication:
            cuda_global_chunk_list = torch.chunk(self.cuda_global_chunk, chunks=self.pg_size)
