    if not self.is_gathered:
        # sanity check
        assert self.cuda_shard is not None

        alloc_storage(self.cuda_global_chunk)
        assert self.cuda_global_chunk.is_contiguous()
        if self.fp8_communication:
            cuda_global_chunk_list = torch.chunk(self.cuda_global_chunk, chunks=self.pg_size)
            work = all_gather_fp8(
                cuda_global_chunk_list, self.cuda_shard, self.torch_pg, fp8_format="e4m3", async_op=async_op
            )
        else:
            work = dist.all_gather_into_tensor(
                self.cuda_global_chunk, self.cuda_shard, self.torch_pg, async_op=async_op
            )

        self.cuda_shard = None
        self.is_gathered = True
        return work
    return None

def _gather(input_, dim=-1, process_group=None, fp8_communication=False, fp8_format="e5m2"):
    # skip if only one rank involved
    world_size = dist.get_world_size(process_group)
    if world_size == 1:
        return input_

    input_ = input_.contiguous()
    tensor_list = [torch.empty_like(input_) for _ in range(world_size)]
    if fp8_communication:
        all_gather_fp8(tensor_list, input_, fp8_format=fp8_format, group=process_group)
    else:
        dist.all_gather(tensor_list, input_, group=process_group)

    output = torch.cat(tensor_list, dim=dim).contiguous()

    return output

