    bound = pysig.bind(*args, **kws)
    if bound.kwargs:
        raise TypingError("unsupported call signature")
    if not isinstance(sig, Signature):
        # If not a signature, `sig` is assumed to be the return type
        if not isinstance(sig, types.Type):
