class ExcelFile(object):
    """
    Class for parsing tabular excel sheets into DataFrame objects.
    Uses xlrd. See read_excel for more documentation

    Parameters
    ----------
    io : string, path object (pathlib.Path or py._path.local.LocalPath),
        file-like object or xlrd workbook
        If a string or path object, expected to be a path to xls or xlsx file
    engine: string, default None
        If io is not a buffer or path, this must be set to identify io.
        Acceptable values are None or xlrd
    """

    def __init__(self, io, **kwds):

        err_msg = "Install xlrd >= 0.9.0 for Excel support"

        try:
            import xlrd
        except ImportError:
            raise ImportError(err_msg)
        else:
            ver = tuple(map(int, xlrd.__VERSION__.split(".")[:2]))
            if ver < (0, 9):  # pragma: no cover
                raise ImportError(err_msg +
                                  ". Current version " + xlrd.__VERSION__)

        # could be a str, ExcelFile, Book, etc.
        self.io = io
        # Always a string
        self._io = _stringify_path(io)

        engine = kwds.pop('engine', None)

        if engine is not None and engine != 'xlrd':
            raise ValueError("Unknown engine: {engine}".format(engine=engine))

        # If io is a url, want to keep the data as bytes so can't pass
        # to get_filepath_or_buffer()
        if _is_url(self._io):
            io = _urlopen(self._io)
        elif not isinstance(self.io, (ExcelFile, xlrd.Book)):
            io, _, _ = get_filepath_or_buffer(self._io)

        if engine == 'xlrd' and isinstance(io, xlrd.Book):
            self.book = io
        elif not isinstance(io, xlrd.Book) and hasattr(io, "read"):
            # N.B. xlrd.Book has a read attribute too
            data = io.read()
            self.book = xlrd.open_workbook(file_contents=data)
        elif isinstance(self._io, compat.string_types):
            self.book = xlrd.open_workbook(self._io)
        else:
            raise ValueError('Must explicitly set engine if not passing in'
                             ' buffer or path for io.')

    def __fspath__(self):
        return self._io

    def parse(self, sheet_name=0, header=0, skiprows=None, skip_footer=0,
              names=None, index_col=None, usecols=None, parse_dates=False,
              date_parser=None, na_values=None, thousands=None,
              convert_float=True, converters=None, true_values=None,
              false_values=None, squeeze=False, **kwds):
        """
        Parse specified sheet(s) into a DataFrame

        Equivalent to read_excel(ExcelFile, ...)  See the read_excel
        docstring for more info on accepted parameters
        """

        return self._parse_excel(sheetname=sheet_name, header=header,
                                 skiprows=skiprows, names=names,
                                 index_col=index_col,
                                 usecols=usecols,
                                 parse_dates=parse_dates,
                                 date_parser=date_parser, na_values=na_values,
                                 thousands=thousands,
                                 skip_footer=skip_footer,
                                 convert_float=convert_float,
                                 converters=converters,
                                 true_values=true_values,
                                 false_values=false_values,
                                 squeeze=squeeze,
                                 **kwds)

    def _should_parse(self, i, usecols):

        def _range2cols(areas):
            """
            Convert comma separated list of column names and column ranges to a
            list of 0-based column indexes.

            >>> _range2cols('A:E')
            [0, 1, 2, 3, 4]
            >>> _range2cols('A,C,Z:AB')
            [0, 2, 25, 26, 27]
            """
            def _excel2num(x):
                "Convert Excel column name like 'AB' to 0-based column index"
                return reduce(lambda s, a: s * 26 + ord(a) - ord('A') + 1,
                              x.upper().strip(), 0) - 1

            cols = []
            for rng in areas.split(','):
                if ':' in rng:
                    rng = rng.split(':')
                    cols += lrange(_excel2num(rng[0]), _excel2num(rng[1]) + 1)
                else:
                    cols.append(_excel2num(rng))
            return cols

        if isinstance(usecols, int):
            return i <= usecols
        elif isinstance(usecols, compat.string_types):
            return i in _range2cols(usecols)
        else:
            return i in usecols

    def _parse_excel(self, sheetname=0, header=0, skiprows=None, names=None,
                     skip_footer=0, index_col=None, usecols=None,
                     parse_dates=False, date_parser=None, na_values=None,
                     thousands=None, convert_float=True, true_values=None,
                     false_values=None, verbose=False, dtype=None,
                     squeeze=False, **kwds):

        skipfooter = kwds.pop('skipfooter', None)
        if skipfooter is not None:
            skip_footer = skipfooter

        _validate_header_arg(header)

        if 'chunksize' in kwds:
            raise NotImplementedError("chunksize keyword of read_excel "
                                      "is not implemented")

        if parse_dates is True and index_col is None:
            warn("The 'parse_dates=True' keyword of read_excel was provided"
                 " without an 'index_col' keyword value.")

        import xlrd
        from xlrd import (xldate, XL_CELL_DATE,
                          XL_CELL_ERROR, XL_CELL_BOOLEAN,
                          XL_CELL_NUMBER)

        epoch1904 = self.book.datemode

        def _parse_cell(cell_contents, cell_typ):
            """converts the contents of the cell into a pandas
               appropriate object"""

            if cell_typ == XL_CELL_DATE:

                if xlrd_0_9_3:
                    # Use the newer xlrd datetime handling.
                    try:
                        cell_contents = \
                            xldate.xldate_as_datetime(cell_contents,
                                                      epoch1904)
                    except OverflowError:
                        return cell_contents
                    # Excel doesn't distinguish between dates and time,
                    # so we treat dates on the epoch as times only.
                    # Also, Excel supports 1900 and 1904 epochs.
                    year = (cell_contents.timetuple())[0:3]
                    if ((not epoch1904 and year == (1899, 12, 31)) or
                            (epoch1904 and year == (1904, 1, 1))):
                        cell_contents = time(cell_contents.hour,
                                             cell_contents.minute,
                                             cell_contents.second,
                                             cell_contents.microsecond)
                else:
                    # Use the xlrd <= 0.9.2 date handling.
                    try:
                        dt = xldate.xldate_as_tuple(cell_contents, epoch1904)

                    except xldate.XLDateTooLarge:
                        return cell_contents

                    if dt[0] < MINYEAR:
                        cell_contents = time(*dt[3:])
                    else:
                        cell_contents = datetime(*dt)

            elif cell_typ == XL_CELL_ERROR:
                cell_contents = np.nan
            elif cell_typ == XL_CELL_BOOLEAN:
                cell_contents = bool(cell_contents)
            elif convert_float and cell_typ == XL_CELL_NUMBER:
                # GH5394 - Excel 'numbers' are always floats
                # it's a minimal perf hit and less suprising
                val = int(cell_contents)
                if val == cell_contents:
                    cell_contents = val
            return cell_contents

        # xlrd >= 0.9.3 can return datetime objects directly.
        if LooseVersion(xlrd.__VERSION__) >= LooseVersion("0.9.3"):
            xlrd_0_9_3 = True
        else:
            xlrd_0_9_3 = False

        ret_dict = False

        # Keep sheetname to maintain backwards compatibility.
        if isinstance(sheetname, list):
            sheets = sheetname
            ret_dict = True
        elif sheetname is None:
            sheets = self.sheet_names
            ret_dict = True
        else:
            sheets = [sheetname]

        # handle same-type duplicates.
        sheets = list(OrderedDict.fromkeys(sheets).keys())

        output = OrderedDict()

        for asheetname in sheets:
            if verbose:
                print("Reading sheet {sheet}".format(sheet=asheetname))

            if isinstance(asheetname, compat.string_types):
                sheet = self.book.sheet_by_name(asheetname)
            else:  # assume an integer if not a string
                sheet = self.book.sheet_by_index(asheetname)

            data = []
            should_parse = {}

            for i in range(sheet.nrows):
                row = []
                for j, (value, typ) in enumerate(zip(sheet.row_values(i),
                                                     sheet.row_types(i))):
                    if usecols is not None and j not in should_parse:
                        should_parse[j] = self._should_parse(j, usecols)

                    if usecols is None or should_parse[j]:
                        row.append(_parse_cell(value, typ))
                data.append(row)

            if sheet.nrows == 0:
                output[asheetname] = DataFrame()
                continue

            if is_list_like(header) and len(header) == 1:
                header = header[0]

            # forward fill and pull out names for MultiIndex column
            header_names = None
            if header is not None:
                if is_list_like(header):
                    header_names = []
                    control_row = [True for x in data[0]]
                    for row in header:
                        if is_integer(skiprows):
                            row += skiprows

                        data[row], control_row = _fill_mi_header(
                            data[row], control_row)
                        header_name, data[row] = _pop_header_name(
                            data[row], index_col)
                        header_names.append(header_name)
                else:
                    data[header] = _trim_excel_header(data[header])

            if is_list_like(index_col):
                # forward fill values for MultiIndex index
                if not is_list_like(header):
                    offset = 1 + header
                else:
                    offset = 1 + max(header)

                for col in index_col:
                    last = data[offset][col]
                    for row in range(offset + 1, len(data)):
                        if data[row][col] == '' or data[row][col] is None:
                            data[row][col] = last
                        else:
                            last = data[row][col]

            has_index_names = is_list_like(header) and len(header) > 1

            # GH 12292 : error when read one empty column from excel file
            try:
                parser = TextParser(data, header=header, index_col=index_col,
                                    has_index_names=has_index_names,
                                    na_values=na_values,
                                    thousands=thousands,
                                    parse_dates=parse_dates,
                                    date_parser=date_parser,
                                    true_values=true_values,
                                    false_values=false_values,
                                    skiprows=skiprows,
                                    skipfooter=skip_footer,
                                    squeeze=squeeze,
                                    dtype=dtype,
                                    **kwds)

                output[asheetname] = parser.read()
                if names is not None:
                    output[asheetname].columns = names
                if not squeeze or isinstance(output[asheetname], DataFrame):
                    output[asheetname].columns = output[
                        asheetname].columns.set_names(header_names)
            except EmptyDataError:
                # No Data, return an empty DataFrame
                output[asheetname] = DataFrame()

        if ret_dict:
            return output
        else:
            return output[asheetname]

    @property
    def sheet_names(self):
        return self.book.sheet_names()

    def close(self):
        """close io if necessary"""
        if hasattr(self.io, 'close'):
            self.io.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def _parse_excel(self, sheetname=0, header=0, skiprows=None, names=None,
                 skip_footer=0, index_col=None, usecols=None,
                 parse_dates=False, date_parser=None, na_values=None,
                 thousands=None, convert_float=True, true_values=None,
                 false_values=None, verbose=False, dtype=None,
                 squeeze=False, **kwds):

    skipfooter = kwds.pop('skipfooter', None)
    if skipfooter is not None:
        skip_footer = skipfooter

    _validate_header_arg(header)

    if 'chunksize' in kwds:
        raise NotImplementedError("chunksize keyword of read_excel "
                                  "is not implemented")

    if parse_dates is True and index_col is None:
        warn("The 'parse_dates=True' keyword of read_excel was provided"
             " without an 'index_col' keyword value.")

    import xlrd
    from xlrd import (xldate, XL_CELL_DATE,
                      XL_CELL_ERROR, XL_CELL_BOOLEAN,
                      XL_CELL_NUMBER)

    epoch1904 = self.book.datemode

    def _parse_cell(cell_contents, cell_typ):
        """converts the contents of the cell into a pandas
           appropriate object"""

        if cell_typ == XL_CELL_DATE:

            if xlrd_0_9_3:
                # Use the newer xlrd datetime handling.
                try:
                    cell_contents = \
                        xldate.xldate_as_datetime(cell_contents,
                                                  epoch1904)
                except OverflowError:
                    return cell_contents
                # Excel doesn't distinguish between dates and time,
                # so we treat dates on the epoch as times only.
                # Also, Excel supports 1900 and 1904 epochs.
                year = (cell_contents.timetuple())[0:3]
                if ((not epoch1904 and year == (1899, 12, 31)) or
                        (epoch1904 and year == (1904, 1, 1))):
                    cell_contents = time(cell_contents.hour,
                                         cell_contents.minute,
                                         cell_contents.second,
                                         cell_contents.microsecond)
            else:
                # Use the xlrd <= 0.9.2 date handling.
                try:
                    dt = xldate.xldate_as_tuple(cell_contents, epoch1904)

                except xldate.XLDateTooLarge:
                    return cell_contents

                if dt[0] < MINYEAR:
                    cell_contents = time(*dt[3:])
                else:
                    cell_contents = datetime(*dt)

        elif cell_typ == XL_CELL_ERROR:
            cell_contents = np.nan
        elif cell_typ == XL_CELL_BOOLEAN:
            cell_contents = bool(cell_contents)
        elif convert_float and cell_typ == XL_CELL_NUMBER:
            # GH5394 - Excel 'numbers' are always floats
            # it's a minimal perf hit and less suprising
            val = int(cell_contents)
            if val == cell_contents:
                cell_contents = val
        return cell_contents

    # xlrd >= 0.9.3 can return datetime objects directly.
    if LooseVersion(xlrd.__VERSION__) >= LooseVersion("0.9.3"):
        xlrd_0_9_3 = True
    else:
        xlrd_0_9_3 = False

    ret_dict = False

    # Keep sheetname to maintain backwards compatibility.
    if isinstance(sheetname, list):
        sheets = sheetname
        ret_dict = True
    elif sheetname is None:
        sheets = self.sheet_names
        ret_dict = True
    else:
        sheets = [sheetname]

    # handle same-type duplicates.
    sheets = list(OrderedDict.fromkeys(sheets).keys())

    output = OrderedDict()

    for asheetname in sheets:
        if verbose:
            print("Reading sheet {sheet}".format(sheet=asheetname))

        if isinstance(asheetname, compat.string_types):
            sheet = self.book.sheet_by_name(asheetname)
        else:  # assume an integer if not a string
            sheet = self.book.sheet_by_index(asheetname)

        data = []
        should_parse = {}

        for i in range(sheet.nrows):
            row = []
            for j, (value, typ) in enumerate(zip(sheet.row_values(i),
                                                 sheet.row_types(i))):
                if usecols is not None and j not in should_parse:
                    should_parse[j] = self._should_parse(j, usecols)

                if usecols is None or should_parse[j]:
                    row.append(_parse_cell(value, typ))
            data.append(row)

        if sheet.nrows == 0:
            output[asheetname] = DataFrame()
            continue

        if is_list_like(header) and len(header) == 1:
            header = header[0]

        # forward fill and pull out names for MultiIndex column
        header_names = None
        if header is not None:
            if is_list_like(header):
                header_names = []
                control_row = [True for x in data[0]]
                for row in header:
                    if is_integer(skiprows):
                        row += skiprows

                    data[row], control_row = _fill_mi_header(
                        data[row], control_row)
                    header_name, data[row] = _pop_header_name(
                        data[row], index_col)
                    header_names.append(header_name)
            else:
                data[header] = _trim_excel_header(data[header])

        if is_list_like(index_col):
            # forward fill values for MultiIndex index
            if not is_list_like(header):
                offset = 1 + header
            else:
                offset = 1 + max(header)

            for col in index_col:
                last = data[offset][col]
                for row in range(offset + 1, len(data)):
                    if data[row][col] == '' or data[row][col] is None:
                        data[row][col] = last
                    else:
                        last = data[row][col]

        has_index_names = is_list_like(header) and len(header) > 1

        # GH 12292 : error when read one empty column from excel file
        try:
            parser = TextParser(data, header=header, index_col=index_col,
                                has_index_names=has_index_names,
                                na_values=na_values,
                                thousands=thousands,
                                parse_dates=parse_dates,
                                date_parser=date_parser,
                                true_values=true_values,
                                false_values=false_values,
                                skiprows=skiprows,
                                skipfooter=skip_footer,
                                squeeze=squeeze,
                                dtype=dtype,
                                **kwds)

            output[asheetname] = parser.read()
            if names is not None:
                output[asheetname].columns = names
            if not squeeze or isinstance(output[asheetname], DataFrame):
                output[asheetname].columns = output[
                    asheetname].columns.set_names(header_names)
        except EmptyDataError:
            # No Data, return an empty DataFrame
            output[asheetname] = DataFrame()

    if ret_dict:
        return output
    else:
        return output[asheetname]

