def append(self, other):
    """
    Append a collection of Index options together

    Parameters
    ----------
    other : Index or list/tuple of indices

    Returns
    -------
    appended : Index
    """
    if not isinstance(other, (list, tuple)):
        other = [other]

    if all((isinstance(o, MultiIndex) and o.nlevels >= self.nlevels)
           for o in other):
        arrays = []
        for i in range(self.nlevels):
            label = self._get_level_values(i)
            appended = [o._get_level_values(i) for o in other]
            arrays.append(label.append(appended))
        return MultiIndex.from_arrays(arrays, names=self.names)

    to_concat = (self.values, ) + tuple(k._values for k in other)
    new_tuples = np.concatenate(to_concat)

    # if all(isinstance(x, MultiIndex) for x in other):
    try:
        return MultiIndex.from_tuples(new_tuples, names=self.names)
    except (TypeError, IndexError):
        return Index(new_tuples)

def difference(self, other):
    """
    Compute sorted set difference of two MultiIndex objects

    Returns
    -------
    diff : MultiIndex
    """
    self._assert_can_do_setop(other)
    other, result_names = self._convert_can_do_setop(other)

    if len(other) == 0:
        return self

    if self.equals(other):
        return MultiIndex(levels=self.levels,
                          labels=[[]] * self.nlevels,
                          names=result_names, verify_integrity=False)

    difference = sorted(set(self._ndarray_values) -
                        set(other._ndarray_values))

    if len(difference) == 0:
        return MultiIndex(levels=[[]] * self.nlevels,
                          labels=[[]] * self.nlevels,
                          names=result_names, verify_integrity=False)
    else:
        return MultiIndex.from_tuples(difference, sortorder=0,
                                      names=result_names)

def test_from_tuples_index_values(idx):
    result = MultiIndex.from_tuples(idx)
    assert (result.values == idx.values).all()

def _wrap_joined_index(self, joined, other):
    names = self.names if self.names == other.names else None
    return MultiIndex.from_tuples(joined, names=names)

def _shallow_copy(self, values=None, **kwargs):
    if values is not None:
        names = kwargs.pop('names', kwargs.pop('name', self.names))
        # discards freq
        kwargs.pop('freq', None)
        return MultiIndex.from_tuples(values, names=names, **kwargs)
    return self.view()

def get_indexer(self, target, method=None, limit=None, tolerance=None):
    method = missing.clean_reindex_fill_method(method)
    target = ensure_index(target)

    # empty indexer
    if is_list_like(target) and not len(target):
        return ensure_platform_int(np.array([]))

    if not isinstance(target, MultiIndex):
        try:
            target = MultiIndex.from_tuples(target)
        except (TypeError, ValueError):

            # let's instead try with a straight Index
            if method is None:
                return Index(self.values).get_indexer(target,
                                                      method=method,
                                                      limit=limit,
                                                      tolerance=tolerance)

    if not self.is_unique:
        raise ValueError('Reindexing only valid with uniquely valued '
                         'Index objects')

    if method == 'pad' or method == 'backfill':
        if tolerance is not None:
            raise NotImplementedError("tolerance not implemented yet "
                                      'for MultiIndex')
        indexer = self._engine.get_indexer(target, method, limit)
    elif method == 'nearest':
        raise NotImplementedError("method='nearest' not implemented yet "
                                  'for MultiIndex; see GitHub issue 9365')
    else:
        indexer = self._engine.get_indexer(target)

    return ensure_platform_int(indexer)

def _convert_can_do_setop(self, other):
    result_names = self.names

    if not hasattr(other, 'names'):
        if len(other) == 0:
            other = MultiIndex(levels=[[]] * self.nlevels,
                               labels=[[]] * self.nlevels,
                               verify_integrity=False)
        else:
            msg = 'other must be a MultiIndex or a list of tuples'
            try:
                other = MultiIndex.from_tuples(other)
            except TypeError:
                raise TypeError(msg)
    else:
        result_names = self.names if self.names == other.names else None
    return other, result_names

def isin(self, values, level=None):
    if level is None:
        values = MultiIndex.from_tuples(values,
                                        names=self.names).values
        return algos.isin(self.values, values)
    else:
        num = self._get_level_number(level)
        levs = self.levels[num]
        labs = self.labels[num]

        sought_labels = levs.isin(values).nonzero()[0]
        if levs.size == 0:
            return np.zeros(len(labs), dtype=np.bool_)
        else:
            return np.lib.arraysetops.in1d(labs, sought_labels)

