def __init__(self, data, axes=None, copy=False, dtype=None,
             fastpath=False):

    if not fastpath:
        if dtype is not None:
            data = data.astype(dtype)
        elif copy:
            data = data.copy()

        if axes is not None:
            for i, ax in enumerate(axes):
                data = data.reindex_axis(ax, axis=i)

    object.__setattr__(self, '_is_copy', None)
    object.__setattr__(self, '_data', data)
    object.__setattr__(self, '_item_cache', {})

def std(self, ddof=1, *args, **kwargs):
    nv.validate_window_func('std', args, kwargs)
    window = self._get_window()
    index, indexi = self._get_index()

    def f(arg, *args, **kwargs):
        minp = _require_min_periods(1)(self.min_periods, window)
        return _zsqrt(libwindow.roll_var(arg, window, minp, indexi,
                                         self.closed, ddof))

    return self._apply(f, 'std', check_minp=_require_min_periods(1),
                       ddof=ddof, **kwargs)

def quantile(self, quantile, interpolation='linear', **kwargs):
    window = self._get_window()
    index, indexi = self._get_index()

    def f(arg, *args, **kwargs):
        minp = _use_window(self.min_periods, window)
        if quantile == 1.0:
            return libwindow.roll_max(arg, window, minp, indexi,
                                      self.closed)
        elif quantile == 0.0:
            return libwindow.roll_min(arg, window, minp, indexi,
                                      self.closed)
        else:
            return libwindow.roll_quantile(arg, window, minp, indexi,
                                           self.closed, quantile,
                                           interpolation)

    return self._apply(f, 'quantile', quantile=quantile,
                       **kwargs)

def _apply(self, func, name=None, window=None, center=None,
           check_minp=None, **kwargs):
    """
    Rolling statistical measure using supplied function. Designed to be
    used with passed-in Cython array-based functions.

    Parameters
    ----------
    func : str/callable to apply
    name : str, optional
       name of this function
    window : int/array, default to _get_window()
    center : bool, default to self.center
    check_minp : function, default to _use_window

    Returns
    -------
    y : type of input
    """
    if center is None:
        center = self.center
    if window is None:
        window = self._get_window()

    if check_minp is None:
        check_minp = _use_window

    blocks, obj, index = self._create_blocks()
    index, indexi = self._get_index(index=index)
    results = []
    for b in blocks:
        values = self._prep_values(b.values)

        if values.size == 0:
            results.append(values.copy())
            continue

        # if we have a string function name, wrap it
        if isinstance(func, compat.string_types):
            cfunc = getattr(libwindow, func, None)
            if cfunc is None:
                raise ValueError("we do not support this function "
                                 "in libwindow.{func}".format(func=func))

            def func(arg, window, min_periods=None, closed=None):
                minp = check_minp(min_periods, window)
                # ensure we are only rolling on floats
                arg = ensure_float64(arg)
                return cfunc(arg,
                             window, minp, indexi, closed, **kwargs)

        # calculation function
        if center:
            offset = _offset(window, center)
            additional_nans = np.array([np.NaN] * offset)

            def calc(x):
                return func(np.concatenate((x, additional_nans)),
                            window, min_periods=self.min_periods,
                            closed=self.closed)
        else:

            def calc(x):
                return func(x, window, min_periods=self.min_periods,
                            closed=self.closed)

        with np.errstate(all='ignore'):
            if values.ndim > 1:
                result = np.apply_along_axis(calc, self.axis, values)
            else:
                result = calc(values)

        if center:
            result = self._center_window(result, window)

        results.append(result)

    return self._wrap_results(results, blocks, obj)

def var(self, ddof=1, *args, **kwargs):
    """
    Compute variance of groups, excluding missing values.

    For multiple groupings, the result index will be a MultiIndex.

    Parameters
    ----------
    ddof : integer, default 1
        degrees of freedom
    """
    nv.validate_groupby_func('var', args, kwargs)
    if ddof == 1:
        try:
            return self._cython_agg_general('var', **kwargs)
        except Exception:
            f = lambda x: x.var(ddof=ddof, **kwargs)
            with _group_selection_context(self):
                return self._python_agg_general(f)
    else:
        f = lambda x: x.var(ddof=ddof, **kwargs)
        with _group_selection_context(self):
            return self._python_agg_general(f)

def apply(self, func, *args, **kwargs):

    func = self._is_builtin_func(func)

    # this is needed so we don't try and wrap strings. If we could
    # resolve functions to their callable functions prior, this
    # wouldn't be needed
    if args or kwargs:
        if callable(func):

            @wraps(func)
            def f(g):
                with np.errstate(all='ignore'):
                    return func(g, *args, **kwargs)
        else:
            raise ValueError('func must be a callable if args or '
                             'kwargs are supplied')
    else:
        f = func

    # ignore SettingWithCopy here in case the user mutates
    with option_context('mode.chained_assignment', None):
        try:
            result = self._python_apply_general(f)
        except Exception:

            # gh-20949
            # try again, with .apply acting as a filtering
            # operation, by excluding the grouping column
            # This would normally not be triggered
            # except if the udf is trying an operation that
            # fails on *some* columns, e.g. a numeric operation
            # on a string grouper column

            with _group_selection_context(self):
                return self._python_apply_general(f)

    return result

def median(self, **kwargs):
    """
    Compute median of groups, excluding missing values.

    For multiple groupings, the result index will be a MultiIndex
    """
    try:
        return self._cython_agg_general('median', **kwargs)
    except GroupByError:
        raise
    except Exception:  # pragma: no cover

        def f(x):
            if isinstance(x, np.ndarray):
                x = Series(x)
            return x.median(axis=self.axis, **kwargs)
        with _group_selection_context(self):
            return self._python_agg_general(f)

def describe(self, **kwargs):
    with _group_selection_context(self):
        result = self.apply(lambda x: x.describe(**kwargs))
        if self.axis == 1:
            return result.T
        return result.unstack()

