def _python_agg_general(self, func, *args, **kwargs):
    func = self._is_builtin_func(func)
    f = lambda x: func(x, *args, **kwargs)

    # iterate through "columns" ex exclusions to populate output dict
    output = {}
    for name, obj in self._iterate_slices():
        try:
            result, counts = self.grouper.agg_series(obj, f)
            output[name] = self._try_cast(result, obj, numeric_only=True)
        except TypeError:
            continue

    if len(output) == 0:
        return self._python_apply_general(f)

    if self.grouper._filter_empty_groups:

        mask = counts.ravel() > 0
        for name, result in compat.iteritems(output):

            # since we are masking, make sure that we have a float object
            values = result
            if is_numeric_dtype(values.dtype):
                values = ensure_float(values)

            output[name] = self._try_cast(values[mask], result)

    return self._wrap_aggregated_output(output)

def _cython_agg_general(self, how, alt=None, numeric_only=True,
                        min_count=-1):
    output = {}
    for name, obj in self._iterate_slices():
        is_numeric = is_numeric_dtype(obj.dtype)
        if numeric_only and not is_numeric:
            continue

        try:
            result, names = self.grouper.aggregate(obj.values, how,
                                                   min_count=min_count)
        except AssertionError as e:
            raise GroupByError(str(e))
        output[name] = self._try_cast(result, obj)

    if len(output) == 0:
        raise DataError('No numeric types to aggregate')

    return self._wrap_aggregated_output(output, names)

def _reduce(self, op, name, axis=0, skipna=True, numeric_only=None,
            filter_type=None, **kwds):
    if numeric_only:
        raise NotImplementedError('Panel.{0} does not implement '
                                  'numeric_only.'.format(name))

    if axis is None and filter_type == 'bool':
        # labels = None
        # constructor = None
        axis_number = None
        axis_name = None
    else:
        # TODO: Make other agg func handle axis=None properly
        axis = self._get_axis_number(axis)
        # labels = self._get_agg_axis(axis)
        # constructor = self._constructor
        axis_name = self._get_axis_name(axis)
        axis_number = self._get_axis_number(axis_name)

    f = lambda x: op(x, axis=axis_number, skipna=skipna, **kwds)

    with np.errstate(all='ignore'):
        result = f(self.values)

    if axis is None and filter_type == 'bool':
        return np.bool_(result)
    axes = self._get_plane_axes(axis_name)
    if result.ndim == 2 and axis_name != self._info_axis_name:
        result = result.T

    return self._construct_return_type(result, axes)

def _get_axis_number(cls, axis):
    axis = cls._AXIS_ALIASES.get(axis, axis)
    if is_integer(axis):
        if axis in cls._AXIS_NAMES:
            return axis
    else:
        try:
            return cls._AXIS_NUMBERS[axis]
        except KeyError:
            pass
    raise ValueError('No axis named {0} for object type {1}'
                     .format(axis, type(cls)))

def _get_axis_name(cls, axis):
    axis = cls._AXIS_ALIASES.get(axis, axis)
    if isinstance(axis, string_types):
        if axis in cls._AXIS_NUMBERS:
            return axis
    else:
        try:
            return cls._AXIS_NAMES[axis]
        except KeyError:
            pass
    raise ValueError('No axis named {0} for object type {1}'
                     .format(axis, type(cls)))

def _construct_return_type(self, result, axes=None):
    """ Return the type for the ndim of the result. """
    ndim = getattr(result, 'ndim', None)

    # need to assume they are the same
    if ndim is None:
        if isinstance(result, dict):
            ndim = getattr(list(compat.itervalues(result))[0], 'ndim', 0)

            # have a dict, so top-level is +1 dim
            if ndim != 0:
                ndim += 1

    # scalar
    if ndim == 0:
        return Series(result)

    # same as self
    elif self.ndim == ndim:
        # return the construction dictionary for these axes
        if axes is None:
            return self._constructor(result)
        return self._constructor(result, **self._construct_axes_dict())

    # sliced
    elif self.ndim == ndim + 1:
        if axes is None:
            return self._constructor_sliced(result)
        return self._constructor_sliced(
            result, **self._extract_axes_for_slice(self, axes))

    raise ValueError('invalid _construct_return_type [self->{self}] '
                     '[result->{result}]'.format(self=self, result=result))

def var(self, ddof=1, *args, **kwargs):
    """
    Compute variance of groups, excluding missing values.

    For multiple groupings, the result index will be a MultiIndex.

    Parameters
    ----------
    ddof : integer, default 1
        degrees of freedom
    """
    nv.validate_groupby_func('var', args, kwargs)
    if ddof == 1:
        try:
            return self._cython_agg_general('var', **kwargs)
        except Exception:
            f = lambda x: x.var(ddof=ddof, **kwargs)
            with _group_selection_context(self):
                return self._python_agg_general(f)
    else:
        f = lambda x: x.var(ddof=ddof, **kwargs)
        with _group_selection_context(self):
            return self._python_agg_general(f)

