def _apply(self, func, **kwargs):
    """
    Rolling statistical measure using supplied function. Designed to be
    used with passed-in Cython array-based functions.

    Parameters
    ----------
    func : str/callable to apply

    Returns
    -------
    y : same type as input argument
    """
    blocks, obj, index = self._create_blocks()
    results = []
    for b in blocks:
        try:
            values = self._prep_values(b.values)
        except TypeError:
            results.append(b.values.copy())
            continue

        if values.size == 0:
            results.append(values.copy())
            continue

        # if we have a string function name, wrap it
        if isinstance(func, compat.string_types):
            cfunc = getattr(libwindow, func, None)
            if cfunc is None:
                raise ValueError("we do not support this function "
                                 "in libwindow.{func}".format(func=func))

            def func(arg):
                return cfunc(arg, self.com, int(self.adjust),
                             int(self.ignore_na), int(self.min_periods))

        results.append(np.apply_along_axis(func, self.axis, values))

    return self._wrap_results(results, blocks, obj)

def _prep_values(self, values=None, kill_inf=True):

    if values is None:
        values = getattr(self._selected_obj, 'values', self._selected_obj)

    # GH #12373 : rolling functions error on float32 data
    # make sure the data is coerced to float64
    if is_float_dtype(values.dtype):
        values = ensure_float64(values)
    elif is_integer_dtype(values.dtype):
        values = ensure_float64(values)
    elif needs_i8_conversion(values.dtype):
        raise NotImplementedError("ops for {action} for this "
                                  "dtype {dtype} are not "
                                  "implemented".format(
                                      action=self._window_type,
                                      dtype=values.dtype))
    else:
        try:
            values = ensure_float64(values)
        except (ValueError, TypeError):
            raise TypeError("cannot handle this type -> {0}"
                            "".format(values.dtype))

    if kill_inf:
        values = values.copy()
        values[np.isinf(values)] = np.NaN

    return values

