            f'Overriding controller cloud: {override_sky_config_dict["jobs"]["controller"]["resources"]["cloud"]}'
        )

    if not override_sky_config_dict:
        yield None
        return

    temp_config_file = tempfile.NamedTemporaryFile(mode='w', suffix='.yaml')
