        TokenType.VAR
        if self._prev_token_type == TokenType.PARAMETER
        else self.KEYWORDS.get(self._text.upper(), TokenType.VAR)
    )

def _extract_string(self, delimiter: str) -> str:
    text = ""
    delim_size = len(delimiter)

