            text += self._char  # type: ignore
            self._advance()

    return text

def _chars(self, size: int) -> str:
    if size == 1:
        return self._char  # type: ignore
    start = self._current - 1
    end = start + size
    if end <= self.size:
        return self.sql[start:end]
