        global _connection_kwargs

        establish_db_conn(fo.config)

class SortBy(ViewStage):
    """Sorts the samples in a collection by the given field(s) or
    expression(s).

    Examples::

        import fiftyone as fo
        import fiftyone.zoo as foz
        from fiftyone import ViewField as F

        dataset = foz.load_zoo_dataset("quickstart")

        #
        # Sort the samples by their `uniqueness` field in ascending order
        #

        stage = fo.SortBy("uniqueness", reverse=False)
        view = dataset.add_stage(stage)

        #
        # Sorts the samples in descending order by the number of detections in
        # their `predictions` field whose bounding box area is less than 0.2
        #

        # Bboxes are in [top-left-x, top-left-y, width, height] format
        bbox = F("bounding_box")
        bbox_area = bbox[2] * bbox[3]

        small_boxes = F("predictions.detections").filter(bbox_area < 0.2)
        stage = fo.SortBy(small_boxes.length(), reverse=True)
        view = dataset.add_stage(stage)

        #
        # Performs a compound sort where samples are first sorted in descending
        # order by number of detections and then in ascending order of
        # uniqueness for samples with the same number of predictions
        #

        stage = fo.SortBy(
            [
                (F("predictions.detections").length(), -1),
                ("uniqueness", 1),
            ]
        )
        view = dataset.add_stage(stage)

        num_objects, uniqueness = view[:5].values(
            [F("predictions.detections").length(), "uniqueness"]
        )
        print(list(zip(num_objects, uniqueness)))

    Args:
        field_or_expr: the field(s) or expression(s) to sort by. This can be
            any of the following:

            -   a field to sort by
            -   an ``embedded.field.name`` to sort by
            -   a :class:`fiftyone.core.expressions.ViewExpression` or a
                `MongoDB aggregation expression <https://docs.mongodb.com/manual/meta/aggregation-quick-reference/#aggregation-expressions>`_
                that defines the quantity to sort by
            -   a list of ``(field_or_expr, order)`` tuples defining a compound
                sort criteria, where ``field_or_expr`` is a field or expression
                as defined above, and ``order`` can be 1 or any string starting
                with "a" for ascending order, or -1 or any string starting with
                "d" for descending order
        reverse (False): whether to return the results in descending order
        create_index (True): whether to create an index, if necessary, to
            optimize the sort. Only applicable when sorting by field(s), not
            expressions
    """

    def __init__(self, field_or_expr, reverse=False, create_index=True):
        self._field_or_expr = field_or_expr
        self._reverse = reverse
        self._create_index = create_index

    @property
    def field_or_expr(self):
        """The field or expression to sort by."""
        return self._field_or_expr

    @property
    def reverse(self):
        """Whether to return the results in descending order."""
        return self._reverse

    @property
    def create_index(self):
        """Whether to create an index, if necessary, to optimize the sort."""
        return self._create_index

    def to_mongo(self, sample_collection):
        field_or_expr = self._get_mongo_field_or_expr()

        if not isinstance(field_or_expr, (list, tuple)):
            field_or_expr = [(field_or_expr, 1)]

        if self._reverse:
            field_or_expr = [(f, -order) for f, order in field_or_expr]

        set_dict = {}
        sort_dict = OrderedDict()
        for idx, (expr, order) in enumerate(field_or_expr, 1):
            if etau.is_str(expr):
                expr, _, _ = sample_collection._handle_id_fields(expr)
                field = expr
            else:
                field = "_sort_field%d" % idx
                set_dict[field] = expr

            sort_dict[field] = order

        pipeline = []

        if set_dict:
            pipeline.append({"$addFields": set_dict})

        pipeline.append({"$sort": sort_dict})

        if set_dict:
            pipeline.append({"$project": {f: False for f in set_dict.keys()}})

        return pipeline

    def _needs_frames(self, sample_collection):
        if not sample_collection._contains_videos():
            return False

        field_or_expr = self._get_mongo_field_or_expr()

        if not isinstance(field_or_expr, (list, tuple)):
            field_or_expr = [(field_or_expr, None)]

        needs_frames = False
        for expr, _ in field_or_expr:
            if etau.is_str(expr):
                needs_frames |= sample_collection._is_frame_field(expr)
            else:
                needs_frames |= foe.is_frames_expr(expr)

        return needs_frames

    def _needs_group_slices(self, sample_collection):
        if sample_collection.media_type != fom.GROUP:
            return None

        field_or_expr = self._get_mongo_field_or_expr()

        if not isinstance(field_or_expr, (list, tuple)):
            field_or_expr = [(field_or_expr, None)]

        group_slices = set()
        for expr, _ in field_or_expr:
            if etau.is_str(expr):
                group_slices.update(sample_collection._get_group_slices(expr))
            else:
                group_slices.update(foe.get_group_slices(expr))

        return list(group_slices)

    def _get_mongo_field_or_expr(self):
        return _serialize_sort_expr(self._field_or_expr)

    def _kwargs(self):
        return [
            ["field_or_expr", self._get_mongo_field_or_expr()],
            ["reverse", self._reverse],
            ["create_index", self._create_index],
        ]

    @classmethod
    def _params(cls):
        return [
            {
                "name": "field_or_expr",
                "type": "field|str|json",
                "placeholder": "field or expression",
            },
            {
                "name": "reverse",
                "type": "bool",
                "default": "False",
                "placeholder": "reverse (default=False)",
            },
            {
                "name": "create_index",
                "type": "bool",
                "default": "True",
                "placeholder": "create_index (default=True)",
            },
        ]

    def validate(self, sample_collection):
        if not self._create_index:
            return

        field_or_expr = self._get_mongo_field_or_expr()

        if etau.is_str(field_or_expr):
            index_spec = field_or_expr.lstrip("$")
            sample_collection.create_index(index_spec)
        elif isinstance(field_or_expr, (list, tuple)) and all(
            etau.is_str(i[0]) for i in field_or_expr
        ):
            index_spec = [(f.lstrip("$"), d) for f, d in field_or_expr]
            sample_collection.create_index(index_spec)

class VectorField(mongoengine.fields.BinaryField, Field):
    """A one-dimensional array field.

    :class:`VectorField` instances accept numeric lists, tuples, and 1D numpy
    array values. The underlying data is serialized and stored in the database
    as zlib-compressed bytes generated by ``numpy.save`` and always retrieved
    as a numpy array.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def __init__(self, description=None, info=None, **kwargs):
        super().__init__(**kwargs)
        self._description = description
        self._info = info

    def to_mongo(self, value):
        if value is None:
            return None

        bytes = fou.serialize_numpy_array(value)
        return super().to_mongo(bytes)

    def to_python(self, value):
        if value is None or isinstance(value, np.ndarray):
            return value

        if isinstance(value, (list, tuple)):
            return np.array(value)

        return fou.deserialize_numpy_array(value)

    def validate(self, value):
        if isinstance(value, np.ndarray):
            if value.ndim > 1:
                self.error("Only 1D arrays may be used in a vector field")
        elif not isinstance(value, (list, tuple, Binary)):
            self.error(
                "Only numpy arrays, lists, and tuples may be used in a "
                "vector field"
            )

class Metadata(DynamicEmbeddedDocument):
    """Base class for storing metadata about generic samples.

    Args:
        size_bytes (None): the size of the media, in bytes
        mime_type (None): the MIME type of the media
    """

    size_bytes = fof.IntField()
    mime_type = fof.StringField()

    @classmethod
    def build_for(cls, path_or_url, mime_type=None):
        """Builds a :class:`Metadata` object for the given file.

        Args:
            path_or_url: the path to the data on disk or a URL
            mime_type (None): the MIME type of the file. If not provided, it
                will be guessed

        Returns:
            a :class:`Metadata`
        """
        if path_or_url.startswith("http"):
            return cls._build_for_url(path_or_url, mime_type=mime_type)

        return cls._build_for_local(path_or_url, mime_type=mime_type)

    @classmethod
    def _build_for_local(cls, filepath, mime_type=None):
        if mime_type is None:
            mime_type = etau.guess_mime_type(filepath)

        size_bytes = os.path.getsize(filepath)

        return cls(size_bytes=size_bytes, mime_type=mime_type)

    @classmethod
    def _build_for_url(cls, url, mime_type=None):
        if mime_type is None:
            mime_type = etau.guess_mime_type(url)

        with requests.get(url, stream=True) as r:
            size_bytes = int(r.headers["Content-Length"])

        return cls(size_bytes=size_bytes, mime_type=mime_type)

class MaskTargetsField(DictField):
    """A :class:`DictField` that stores mapping between integer keys or RGB
    string hex keys and string targets.

    If this field is not set, its default value is ``{}``.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def __init__(self, **kwargs):
        if "field" not in kwargs:
            kwargs["field"] = StringField()

        super().__init__(**kwargs)

    def to_mongo(self, value):
        if value is None:
            return None

        return super().to_mongo({str(k): v for k, v in value.items()})

    def to_python(self, value):
        if value is None:
            return None

        if is_integer_mask_targets(value):
            return {int(k): v for k, v in value.items()}

        return value

    def validate(self, value):
        if not isinstance(value, dict):
            self.error("Value must be a dict")

        if not (is_integer_mask_targets(value) or is_rgb_mask_targets(value)):
            self.error(
                "Mask target field keys must all either be integer keys or "
                "string RGB hex keys (like #012abc)"
            )

        if self.field is not None:
            for _value in value.values():
                self.field.validate(_value)

class EmbeddedDocumentField(mongoengine.fields.EmbeddedDocumentField, Field):
    """A field that stores instances of a given type of
    :class:`fiftyone.core.odm.BaseEmbeddedDocument` object.

    Args:
        document_type: the :class:`fiftyone.core.odm.BaseEmbeddedDocument` type
            stored in this field
        description (None): an optional description
        info (None): an optional info dict
    """

    def __init__(self, document_type, description=None, info=None, **kwargs):
        super().__init__(document_type, **kwargs)
        self.fields = kwargs.get("fields", [])
        self._description = description
        self._info = info
        self._selected_fields = None
        self._excluded_fields = None
        self.__fields = None

    def __str__(self):
        return "%s(%s)" % (
            etau.get_class_name(self),
            etau.get_class_name(self.document_type),
        )

    def _set_dataset(self, dataset, path):
        super()._set_dataset(dataset, path)

        for field_name, field in self._fields.items():
            if not isinstance(field, Field):
                continue

            if path is not None:
                _path = path + "." + field_name
            else:
                _path = None

            field._set_dataset(dataset, _path)

    @property
    def _fields(self):
        if self.__fields is None:
            # Must initialize now because `document_type` could have been a
            # string at class instantiation
            self.__fields = deepcopy(self.document_type._fields)
            self.__fields.update({f.name: f for f in self.fields})

        return self.__fields

    def _use_view(self, selected_fields=None, excluded_fields=None):
        if selected_fields is not None and excluded_fields is not None:
            selected_fields = selected_fields.difference(excluded_fields)
            excluded_fields = None

        self._selected_fields = selected_fields
        self._excluded_fields = excluded_fields

    def _get_field_names(self, include_private=False, use_db_fields=False):
        field_names = tuple(self._fields.keys())

        if not include_private:
            field_names = tuple(
                fn for fn in field_names if not fn.startswith("_")
            )

        if self._selected_fields is not None:
            field_names = tuple(
                fn for fn in field_names if fn in self._selected_fields
            )

        if self._excluded_fields is not None:
            field_names = tuple(
                fn for fn in field_names if fn not in self._excluded_fields
            )

        if use_db_fields:
            return self._to_db_fields(field_names)

        return field_names

    def _get_default_fields(self, include_private=False, use_db_fields=False):
        field_names = tuple(self.document_type._fields.keys())

        if not include_private:
            field_names = tuple(
                f for f in field_names if not f.startswith("_")
            )

        if use_db_fields:
            field_names = self._to_db_fields(field_names)

        return field_names

    def _to_db_fields(self, field_names):
        return tuple(self._fields[f].db_field or f for f in field_names)

    def has_field(self, path):
        """Determines whether this field has the given embedded field.

        Args:
            path: the field name or ``embedded.field.name``

        Returns:
            True/False
        """
        return self.get_field(path) is not None

    def get_field(self, path):
        """Returns the field for the provided path, or ``None``.

        Args:
            path: a field name or ``embedded.field.name``

        Returns:
            a :class:`Field` instance or ``None``
        """
        chunks = path.split(".", 1)
        if len(chunks) > 1:
            field = self._fields.get(chunks[0], None)
            while isinstance(field, ListField):
                field = field.field

            if not isinstance(field, EmbeddedDocumentField):
                return None

            return field.get_field(chunks[1])

        return self._fields.get(path, None)

    def get_field_schema(
        self,
        ftype=None,
        embedded_doc_type=None,
        include_private=False,
        flat=False,
    ):
        """Returns a schema dictionary describing the fields of the embedded
        document field.

        Args:
            ftype (None): an optional field type or iterable of types to which
                to restrict the returned schema. Must be subclass(es) of
                :class:`Field`
            embedded_doc_type (None): an optional embedded document type or
                iterable of types to which to restrict the returned schema.
                Must be subclass(es) of
                :class:`fiftyone.core.odm.BaseEmbeddedDocument`
            include_private (False): whether to include fields that start with
                ``_`` in the returned schema
            flat (False): whether to return a flattened schema where all
                embedded document fields are included as top-level keys

        Returns:
             a dict mapping field names to field types
        """
        validate_type_constraints(
            ftype=ftype, embedded_doc_type=embedded_doc_type
        )

        schema = {}
        for name in self._get_field_names(include_private=include_private):
            field = self._fields[name]
            if matches_type_constraints(
                field, ftype=ftype, embedded_doc_type=embedded_doc_type
            ):
                schema[name] = field

        if flat:
            schema = flatten_schema(
                schema,
                ftype=ftype,
                embedded_doc_type=embedded_doc_type,
                include_private=include_private,
            )

        return schema

    def validate(self, value, **kwargs):
        if not isinstance(value, self.document_type):
            self.error(
                "Expected %s; found %s" % (self.document_type, type(value))
            )

        for k, v in self._fields.items():
            try:
                val = value[k]
            except KeyError:
                val = None

            if val is not None:
                v.validate(val)

    def _merge_fields(self, path, field, validate=True, recursive=True):
        if validate:
            foo.validate_fields_match(path, field, self)
        elif not isinstance(field, EmbeddedDocumentField):
            return None

        new_schema = {}
        existing_fields = self._fields

        for name, _field in field._fields.items():
            _existing_field = existing_fields.get(name, None)
            if _existing_field is not None:
                if validate:
                    _path = path + "." + name
                    foo.validate_fields_match(_path, _field, _existing_field)

                if recursive:
                    while isinstance(_existing_field, ListField):
                        _existing_field = _existing_field.field
                        if isinstance(_field, ListField):
                            _field = _field.field
                        else:
                            _existing_field = None

                    if isinstance(_existing_field, EmbeddedDocumentField):
                        _path = path + "." + name
                        _new_schema = _existing_field._merge_fields(
                            _path,
                            _field,
                            validate=validate,
                            recursive=recursive,
                        )

                        if _new_schema:
                            new_schema.update(_new_schema)
            else:
                _path = path + "." + name
                new_schema[_path] = _field

        return new_schema

    def _declare_field(self, dataset, path, field_or_doc):
        if isinstance(field_or_doc, foo.SampleFieldDocument):
            field = field_or_doc.to_field()
        else:
            field = field_or_doc

        field_name = field.name

        self.fields = [f for f in self.fields if f.name != field_name]
        self.fields.append(field)

        prev = self._fields.pop(field_name, None)

        if prev is not None:
            prev._set_dataset(None, None)
            field.required = prev.required
            field.null = prev.null

        field._set_dataset(dataset, path)
        self._fields[field_name] = field

    def _update_field(self, dataset, field_name, new_path, field):
        new_field_name = field.name

        self.fields = [
            f if f.name != field_name else field for f in self.fields
        ]
        prev = self._fields.pop(field_name, None)

        if prev is not None:
            prev._set_dataset(None, None)

        field._set_dataset(dataset, new_path)
        self._fields[new_field_name] = field

    def _undeclare_field(self, field_name):
        self.fields = [f for f in self.fields if f.name != field_name]
        prev = self._fields.pop(field_name, None)

        if prev is not None:
            prev._set_dataset(None, None)

class ExcludeBy(ViewStage):
    """Excludes the samples with the given field values from a collection.

    This stage is typically used to work with categorical fields (strings,
    ints, and bools). If you want to exclude samples based on floating point
    fields, use :class:`Match`.

    Examples::

        import fiftyone as fo

        dataset = fo.Dataset()
        dataset.add_samples(
            [
                fo.Sample(filepath="image%d.jpg" % i, int=i, str=str(i))
                for i in range(10)
            ]
        )

        #
        # Create a view excluding samples whose `int` field have the given
        # values
        #

        stage = fo.ExcludeBy("int", [1, 9, 3, 7, 5])
        view = dataset.add_stage(stage)
        print(view.head(5))

        #
        # Create a view excluding samples whose `str` field have the given
        # values
        #

        stage = fo.ExcludeBy("str", ["1", "9", "3", "7", "5"])
        view = dataset.add_stage(stage)
        print(view.head(5))

    Args:
        field: a field or ``embedded.field.name``
        values: a value or iterable of values to exclude by
    """

    def __init__(self, field, values):
        if etau.is_container(values):
            values = list(values)
        else:
            values = [values]

        self._field = field
        self._values = values

    @property
    def field(self):
        """The field whose values to exclude by."""
        return self._field

    @property
    def values(self):
        """The list of values to exclude by."""
        return self._values

    def to_mongo(self, sample_collection):
        path, is_id_field, _ = sample_collection._handle_id_fields(self._field)

        if is_id_field:
            values = [
                value if isinstance(value, ObjectId) else ObjectId(value)
                for value in self._values
            ]
        else:
            values = self._values

        return [{"$match": {path: {"$not": {"$in": values}}}}]

    def _kwargs(self):
        return [["field", self._field], ["values", self._values]]

    @classmethod
    def _params(cls):
        return [
            {"name": "field", "type": "field|str", "placeholder": "field"},
            {
                "name": "values",
                "type": "json",
                "placeholder": "list,of,values",
            },
        ]

class FrameNumberField(IntField):
    """A video frame number field.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def validate(self, value):
        try:
            fofu.validate_frame_number(value)
        except fofu.FrameError as e:
            self.error(str(e))

class PolylinePointsField(ListField):
    """A list of lists of ``(x, y)`` coordinate pairs.

    If this field is not set, its default value is ``[]``.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def __str__(self):
        return etau.get_class_name(self)

    def validate(self, value):
        # Only validate value[0] and value[0][0], for efficiency
        if (
            not isinstance(value, (list, tuple))
            or (value and not isinstance(value[0], (list, tuple)))
            or (
                value
                and value[0]
                and (
                    not isinstance(value[0][0], (list, tuple))
                    or len(value[0][0]) != 2
                )
            )
        ):
            self.error(
                "Polyline points fields must contain a list of lists of "
                "(x, y) pairs"
            )

class Concat(ViewStage):
    """Concatenates the contents of the given
    :class:`fiftyone.core.collections.SampleCollection` to this collection.

    Examples::

        import fiftyone as fo
        import fiftyone.zoo as foz
        from fiftyone import ViewField as F

        dataset = foz.load_zoo_dataset("quickstart")

        #
        # Concatenate two views
        #

        view1 = dataset.match(F("uniqueness") < 0.2)
        view2 = dataset.match(F("uniqueness") > 0.7)

        stage = fo.Concat(view2)
        view = view1.add_stage(stage)

        print(view1)
        print(view2)
        print(view)

        #
        # Concatenate two patches views
        #

        gt_objects = dataset.to_patches("ground_truth")

        patches1 = gt_objects[:50]
        patches2 = gt_objects[-50:]

        stage = fo.Concat(patches2)
        patches = patches1.add_stage(stage)

        print(patches1)
        print(patches2)
        print(patches)

    Args:
        samples: a :class:`fiftyone.core.collections.SampleCollection` whose
            contents to append to this collection
    """

    def __init__(self, samples):
        samples, view = self._parse_params(samples)

        self._samples = samples
        self._view = view

    @property
    def samples(self):
        """The :class:`fiftyone.core.collections.SampleCollection` whose
        contents to append to this collection.
        """
        return self._view

    def to_mongo(self, _):
        return [
            {
                "$unionWith": {
                    "coll": self._view._dataset._sample_collection_name,
                    "pipeline": self._view._pipeline(
                        detach_frames=True, detach_groups=True
                    ),
                }
            }
        ]

    def validate(self, sample_collection):
        if sample_collection._dataset != self._view._dataset:
            if sample_collection._root_dataset == self._view._root_dataset:
                raise ValueError(
                    "When concatenating samples from generated views (e.g. "
                    "patches or frames), all views must be derived from the "
                    "same root generated view"
                )
            else:
                raise ValueError(
                    "Cannot concatenate samples from different datasets"
                )

    def _kwargs(self):
        return [["samples", self._samples]]

    @classmethod
    def _params(cls):
        return [{"name": "samples", "type": "json", "placeholder": ""}]

    def _parse_params(self, samples):
        if not isinstance(samples, (foc.SampleCollection, dict)):
            raise ValueError(
                "`samples` must be a SampleCollection or a serialized "
                "representation of one, but found %s" % samples
            )

        view = None

        if isinstance(samples, foc.SampleCollection):
            view = samples.view()
            samples = None

        if view is None:
            view = self._load_view(samples)

        if samples is None:
            samples = self._serialize_view(view)

        return samples, view

    def _serialize_view(self, view):
        return {
            "dataset": view._root_dataset.name,
            "stages": view._serialize(include_uuids=False),
        }

    def _load_view(self, d):
        dataset = fod.load_dataset(d["dataset"])
        return fov.DatasetView._build(dataset, d["stages"])

class FacetAggregations(Aggregation):
    """Efficiently computes a set of aggregations rooted at a common path using
    faceted computations.

    .. note::

        All ``aggregations`` provided to this method are interpreted relative
        to the provided ``field_name``.

    Examples::

        import fiftyone as fo

        dataset = fo.Dataset()
        dataset.add_samples(
            [
                fo.Sample(
                    filepath="/path/to/image1.png",
                    tags=["sunny"],
                    predictions=fo.Detections(
                        detections=[
                            fo.Detection(label="cat", confidence=0.4),
                            fo.Detection(label="dog", confidence=0.5),
                        ]
                    ),
                ),
                fo.Sample(
                    filepath="/path/to/image2.png",
                    tags=["sunny", "cloudy"],
                    predictions=fo.Detections(
                        detections=[
                            fo.Detection(label="cat", confidence=0.6),
                            fo.Detection(label="rabbit", confidence=0.7),
                        ]
                    ),
                ),
                fo.Sample(
                    filepath="/path/to/image3.png",
                    predictions=None,
                ),
            ]
        )

        #
        # Compute prediction label value counts and confidence bounds
        #

        values, bounds = dataset.aggregate(
            fo.FacetAggregations(
                "predictions.detections",
                [fo.CountValues("label"), fo.Bounds("confidence")]
            )
        )
        print(values)  # label value counts
        print(bounds)  # confidence bounds

    Args:
        field_name: a field name or ``embedded.field.name``
        aggregations: a list or dict of :class:`Aggregation` instances
    """

    def __init__(self, field_name, aggregations, _compiled=False):
        raw_aggregations, aggregations, is_dict = self._parse_aggregations(
            field_name, aggregations
        )

        super().__init__(field_name)
        self._raw_aggregations = raw_aggregations
        self._aggregations = aggregations
        self._compiled = _compiled
        self._is_dict = is_dict

    def _serialize(self, include_uuid=True):
        d = {
            "_cls": etau.get_class_name(self),
            "kwargs": self._kwargs(include_uuid=include_uuid),
        }

        if include_uuid:
            if self._uuid is None:
                self._uuid = str(uuid.uuid4())

            d["_uuid"] = self._uuid

        return d

    def _kwargs(self, include_uuid=True):
        aggregations = self._serialize_aggregations(
            self._raw_aggregations, include_uuid=include_uuid
        )

        return [
            ["field_name", self._field_name],
            ["aggregations", aggregations],
            ["_compiled", self._compiled],
        ]

    def default_result(self):
        """Returns the default result for this aggregation.

        Returns:
            the default result of each sub-aggregation in the same container
            type as the sub-aggregations were provided (list or dict)
        """
        data = {
            key: agg.default_result()
            for key, agg in self._aggregations.items()
        }

        if self._is_dict:
            return data

        results = [None] * len(self._aggregations)
        for idx, d in data.items():
            results[idx] = d

        return results

    def parse_result(self, d):
        """Parses the output of :meth:`to_mongo`.

        Args:
            d: the result dict

        Returns:
            the parsed result of each sub-aggregation in the same container
            type as the sub-aggregations were provided (list or dict)
        """
        data = {}
        for key, agg in self._aggregations.items():
            try:
                data[key] = agg.parse_result(d[self._get_key(key, agg)][0])
            except:
                data[key] = agg.default_result()

        if self._is_dict:
            return data

        results = [None] * len(self._aggregations)
        for idx, d in data.items():
            results[idx] = d

        return results

    def to_mongo(self, sample_collection, context=None):
        path, pipeline, _, _, _ = _parse_field_and_expr(
            sample_collection, self._field_name, context=context
        )
        self._path = path

        facets = {}
        for key, agg in self._aggregations.items():
            facets[self._get_key(key, agg)] = agg.to_mongo(
                sample_collection, context=self.field_name
            )

        pipeline += [{"$facet": facets}]

        return pipeline

    @staticmethod
    def _get_key(key, agg):
        return (
            agg.field_name.replace(".", "_")
            + "_"
            + agg.__class__.__name__
            + str(key)
        )

    @staticmethod
    def _parse_aggregations(field_name, aggregations):
        raw_aggregations = deepcopy(aggregations)
        is_dict = isinstance(aggregations, dict)

        if not is_dict:
            aggregations = {idx: agg for idx, agg in enumerate(aggregations)}

        for key, agg in aggregations.items():
            if isinstance(agg, dict):
                agg = Aggregation._from_dict(agg)
                aggregations[key] = agg

            if agg._field_name:
                agg._field_name = field_name + "." + agg._field_name
            else:
                agg._field_name = field_name

        return raw_aggregations, aggregations, is_dict

    @staticmethod
    def _serialize_aggregations(aggregations, include_uuid=True):
        if isinstance(aggregations, dict):
            return {
                k: _serialize_aggregation(agg, include_uuid=include_uuid)
                for k, agg in aggregations.items()
            }

        return [
            _serialize_aggregation(agg, include_uuid=include_uuid)
            for agg in aggregations
        ]

class FrameSupportField(ListField):
    """A ``[first, last]`` frame support in a video.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def __init__(self, **kwargs):
        if "field" not in kwargs:
            kwargs["field"] = IntField()

        super().__init__(**kwargs)

    def __str__(self):
        return etau.get_class_name(self)

    def validate(self, value):
        if (
            not isinstance(value, (list, tuple))
            or len(value) != 2
