class LimitLabels(ViewStage):
    """Limits the number of :class:`fiftyone.core.labels.Label` instances in
    the specified labels list field of each sample in a collection.

    The specified ``field`` must be one of the following types:

    -   :class:`fiftyone.core.labels.Classifications`
    -   :class:`fiftyone.core.labels.Detections`
    -   :class:`fiftyone.core.labels.Keypoints`
    -   :class:`fiftyone.core.labels.Polylines`

    Examples::

        import fiftyone as fo
        from fiftyone import ViewField as F

        dataset = fo.Dataset()
        dataset.add_samples(
            [
                fo.Sample(
                    filepath="/path/to/image1.png",
                    predictions=fo.Detections(
                        detections=[
                            fo.Detection(
                                label="cat",
                                bounding_box=[0.1, 0.1, 0.5, 0.5],
                                confidence=0.9,
                            ),
                            fo.Detection(
                                label="dog",
                                bounding_box=[0.2, 0.2, 0.3, 0.3],
                                confidence=0.8,
                            ),
                        ]
                    ),
                ),
                fo.Sample(
                    filepath="/path/to/image2.png",
                    predictions=fo.Detections(
                        detections=[
                            fo.Detection(
                                label="cat",
                                bounding_box=[0.5, 0.5, 0.4, 0.4],
                                confidence=0.95,
                            ),
                            fo.Detection(label="rabbit"),
                        ]
                    ),
                ),
                fo.Sample(
                    filepath="/path/to/image4.png",
                    predictions=None,
                ),
            ]
        )

        #
        # Only include the first detection in the `predictions` field of each
        # sample
        #

        stage = fo.LimitLabels("predictions", 1)
        view = dataset.add_stage(stage)

    Args:
        field: the labels list field to filter
        limit: the maximum number of labels to include in each labels list.
            If a non-positive number is provided, all lists will be empty
    """

    def __init__(self, field, limit):
        self._field = field
        self._limit = limit
        self._labels_list_field = None
        self._is_frame_field = None

    @property
    def field(self):
        """The labels field to limit."""
        return self._field

    @property
    def limit(self):
        """The maximum number of labels to allow in each labels list."""
        return self._limit

    def get_filtered_fields(self, sample_collection, frames=False):
        if frames == self._is_frame_field:
            list_path, _ = sample_collection._handle_frame_field(
                self._labels_list_field
            )
            return [list_path]

        return None

    def to_mongo(self, sample_collection):
        if self._labels_list_field is None:
            raise ValueError(
                "`validate()` must be called before using a %s stage"
                % self.__class__
            )

        limit = max(self._limit, 0)
        root, leaf = self._labels_list_field.rsplit(".", 1)

        expr = (F() != None).if_else(
            F().set_field(leaf, F(leaf)[:limit]),
            None,
        )
        pipeline, _ = sample_collection._make_set_field_pipeline(root, expr)

        return pipeline

    def _needs_frames(self, sample_collection):
        return self._is_frame_field

    def _needs_group_slices(self, sample_collection):
        if sample_collection.media_type != fom.GROUP:
            return None

        return sample_collection._get_group_slices(self._field)

    def _kwargs(self):
        return [
            ["field", self._field],
            ["limit", self._limit],
        ]

    @classmethod
    def _params(cls):
        return [
            {"name": "field", "type": "field"},
            {"name": "limit", "type": "int", "placeholder": "int"},
        ]

    def validate(self, sample_collection):
        list_field, is_list_field, is_frame_field = _parse_labels_field(
            sample_collection, self._field
        )

        if not is_list_field:
            raise ValueError(
                "Field '%s' does not contain a list of labels" % self._field
            )

        self._labels_list_field = list_field
        self._is_frame_field = is_frame_field

class ToPatches(ViewStage):
    """Creates a view that contains one sample per object patch in the
    specified field of a collection.

    A ``sample_id`` field will be added that records the sample ID from which
    each patch was taken.

    By default, fields other than ``field`` and the default sample fields will
    not be included in the returned view.

    Examples::

        import fiftyone as fo
        import fiftyone.zoo as foz

        dataset = foz.load_zoo_dataset("quickstart")

        session = fo.launch_app(dataset)

        #
        # Create a view containing the ground truth patches
        #

        stage = fo.ToPatches("ground_truth")
        view = dataset.add_stage(stage)
        print(view)

        session.view = view

    Args:
        field: the patches field, which must be of type
            :class:`fiftyone.core.labels.Detections`,
            :class:`fiftyone.core.labels.Polylines`, or
            :class:`fiftyone.core.labels.Keypoints`
        config (None): an optional dict of keyword arguments for
            :meth:`fiftyone.core.patches.make_patches_dataset` specifying how
            to perform the conversion
        **kwargs: optional keyword arguments for
            :meth:`fiftyone.core.patches.make_patches_dataset` specifying how
            to perform the conversion
    """

    def __init__(self, field, config=None, _state=None, **kwargs):
        if kwargs:
            if config is None:
                config = kwargs
            else:
                config.update(kwargs)

        self._field = field
        self._config = config
        self._state = _state

    @property
    def has_view(self):
        return True

    @property
    def field(self):
        """The patches field."""
        return self._field

    @property
    def config(self):
        """Parameters specifying how to perform the conversion."""
        return self._config

    def load_view(self, sample_collection):
        state = {
            "dataset": sample_collection.dataset_name,
            "stages": sample_collection.view()._serialize(include_uuids=False),
            "field": self._field,
            "config": self._config,
        }

        last_state = deepcopy(self._state)
        if last_state is not None:
            name = last_state.pop("name", None)
        else:
            name = None

        if state != last_state or not fod.dataset_exists(name):
            kwargs = self._config or {}
            patches_dataset = fop.make_patches_dataset(
                sample_collection, self._field, **kwargs
            )

            # Other views may use the same generated dataset, so reuse the old
            # name if possible
            if name is not None and state == last_state:
                patches_dataset.name = name

            state["name"] = patches_dataset.name
            self._state = state
        else:
            patches_dataset = fod.load_dataset(name)

        return fop.PatchesView(sample_collection, self, patches_dataset)

    def _kwargs(self):
        return [
            ["field", self._field],
            ["config", self._config],
            ["_state", self._state],
        ]

    @classmethod
    def _params(self):
        return [
            {"name": "field", "type": "field", "placeholder": "label field"},
            {
                "name": "config",
                "type": "NoneType|json",
                "default": "None",
                "placeholder": "config (default=None)",
            },
            {"name": "_state", "type": "NoneType|json", "default": "None"},
        ]

class KeypointsField(ListField):
    """A list of ``(x, y)`` coordinate pairs.

    If this field is not set, its default value is ``[]``.

    Args:
        description (None): an optional description
        info (None): an optional info dict
    """

    def __str__(self):
        return etau.get_class_name(self)

    def validate(self, value):
        # Only validate value[0], for efficiency
        if not isinstance(value, (list, tuple)) or (
            value
            and (not isinstance(value[0], (list, tuple)) or len(value[0]) != 2)
        ):
            self.error("Keypoints fields must contain a list of (x, y) pairs")

class ImageMetadata(Metadata):
    """Class for storing metadata about image samples.

    Args:
        size_bytes (None): the size of the image on disk, in bytes
        mime_type (None): the MIME type of the image
        width (None): the width of the image, in pixels
        height (None): the height of the image, in pixels
        num_channels (None): the number of channels in the image
    """

    width = fof.IntField()
    height = fof.IntField()
    num_channels = fof.IntField()

    @classmethod
    def build_for(cls, img_or_path_or_url, mime_type=None):
        """Builds an :class:`ImageMetadata` object for the given image.

        Args:
            img_or_path_or_url: an image, an image path on disk, or a URL
            mime_type (None): the MIME type of the image. If not provided, it
                will be guessed

        Returns:
            an :class:`ImageMetadata`
        """
        if not etau.is_str(img_or_path_or_url):
            return cls._build_for_img(img_or_path_or_url, mime_type=mime_type)

        if img_or_path_or_url.startswith("http"):
            return cls._build_for_url(img_or_path_or_url, mime_type=mime_type)

        return cls._build_for_local(img_or_path_or_url, mime_type=mime_type)

    @classmethod
    def _build_for_local(cls, path, mime_type=None):
        size_bytes = os.path.getsize(path)

        if mime_type is None:
            mime_type = etau.guess_mime_type(path)

        with open(path, "rb") as f:
            width, height, num_channels = get_image_info(f)

        return cls(
            size_bytes=size_bytes,
            mime_type=mime_type,
            width=width,
            height=height,
            num_channels=num_channels,
        )

    @classmethod
    def _build_for_url(cls, url, mime_type=None):
        if mime_type is None:
            mime_type = etau.guess_mime_type(url)

        with requests.get(url, stream=True) as r:
            size_bytes = int(r.headers["Content-Length"])
            width, height, num_channels = get_image_info(fou.ResponseStream(r))

        return cls(
            size_bytes=size_bytes,
            mime_type=mime_type,
            width=width,
            height=height,
            num_channels=num_channels,
        )

    @classmethod
    def _build_for_img(cls, img, mime_type=None):
        size_bytes = img.nbytes
        height, width = img.shape[:2]
        try:
            num_channels = img.shape[2]
        except IndexError:
            num_channels = 1

        return cls(
            size_bytes=size_bytes,
            mime_type=mime_type,
            width=width,
            height=height,
            num_channels=num_channels,
        )

class ToTrajectories(ViewStage):
    """Creates a view that contains one clip for each unique object trajectory
    defined by their ``(label, index)`` in a frame-level field of a video
    collection.

    The returned view will contain:

    -   A ``sample_id`` field that records the sample ID from which each clip
        was taken
    -   A ``support`` field that records the ``[first, last]`` frame support of
        each clip
    -   A sample-level label field that records the ``label`` and ``index`` of
        each trajectory

    Examples::

        import fiftyone as fo
        import fiftyone.zoo as foz
        from fiftyone import ViewField as F

        dataset = foz.load_zoo_dataset("quickstart-video")

        #
        # Create a trajectories view for the vehicles in the dataset
        #

        stage1 = fo.FilterLabels("frames.detections", F("label") == "vehicle")
        stage2 = fo.ToTrajectories("frames.detections")
        trajectories = dataset.add_stage(stage1).add_stage(stage2)

        print(trajectories)

    Args:
        field: a frame-level label list field of any of the following types:

            -   :class:`fiftyone.core.labels.Detections`
            -   :class:`fiftyone.core.labels.Polylines`
            -   :class:`fiftyone.core.labels.Keypoints`
        config (None): an optional dict of keyword arguments for
            :meth:`fiftyone.core.clips.make_clips_dataset` specifying how to
            perform the conversion
        **kwargs: optional keyword arguments for
            :meth:`fiftyone.core.clips.make_clips_dataset` specifying how to
            perform the conversion
    """

    def __init__(self, field, config=None, _state=None, **kwargs):
        if kwargs:
            if config is None:
                config = kwargs
            else:
                config.update(kwargs)

        self._field = field
        self._config = config
        self._state = _state

    @property
    def has_view(self):
        return True

    @property
    def field(self):
        """The label field for which to extract trajectories."""
        return self._field

    @property
    def config(self):
        """Parameters specifying how to perform the conversion."""
        return self._config

    def load_view(self, sample_collection):
        state = {
            "dataset": sample_collection.dataset_name,
            "stages": sample_collection.view()._serialize(include_uuids=False),
            "field": self._field,
            "config": self._config,
        }

        last_state = deepcopy(self._state)
        if last_state is not None:
            name = last_state.pop("name", None)
        else:
            name = None

        if state != last_state or not fod.dataset_exists(name):
            kwargs = self._config or {}
            clips_dataset = focl.make_clips_dataset(
                sample_collection, self._field, trajectories=True, **kwargs
            )

            state["name"] = clips_dataset.name
            self._state = state
        else:
            clips_dataset = fod.load_dataset(name)

        return focl.TrajectoriesView(sample_collection, self, clips_dataset)

    def _kwargs(self):
        return [
            ["field", self._field],
            ["config", self._config],
            ["_state", self._state],
        ]

    @classmethod
    def _params(self):
        return [
            {
                "name": "field",
                "type": "field",
                "placeholder": "field",
            },
            {
                "name": "config",
                "type": "NoneType|json",
                "default": "None",
                "placeholder": "config (default=None)",
            },
            {"name": "_state", "type": "NoneType|json", "default": "None"},
        ]

class SelectGroupSlices(ViewStage):
    """Selects the samples in a group collection from the given slice(s).

    The returned view is a flattened non-grouped view containing only the
    slice(s) of interest.

    .. note::

        This stage performs a ``$lookup`` that pulls the requested slice(s) for
        each sample in the input collection from the source dataset. As a
        result, this stage always emits *unfiltered samples*.

    Examples::

        import fiftyone as fo

        dataset = fo.Dataset()
        dataset.add_group_field("group", default="ego")

        group1 = fo.Group()
        group2 = fo.Group()

        dataset.add_samples(
            [
                fo.Sample(
                    filepath="/path/to/left-image1.jpg",
                    group=group1.element("left"),
                ),
                fo.Sample(
                    filepath="/path/to/video1.mp4",
                    group=group1.element("ego"),
                ),
                fo.Sample(
                    filepath="/path/to/right-image1.jpg",
                    group=group1.element("right"),
                ),
                fo.Sample(
                    filepath="/path/to/left-image2.jpg",
                    group=group2.element("left"),
                ),
                fo.Sample(
                    filepath="/path/to/video2.mp4",
                    group=group2.element("ego"),
                ),
                fo.Sample(
                    filepath="/path/to/right-image2.jpg",
                    group=group2.element("right"),
                ),
            ]
        )

        #
        # Retrieve the samples from the "ego" group slice
        #

        stage = fo.SelectGroupSlices("ego")
        view = dataset.add_stage(stage)

        #
        # Retrieve the samples from the "left" or "right" group slices
        #

        stage = fo.SelectGroupSlices(["left", "right"])
        view = dataset.add_stage(stage)

        #
        # Retrieve all image samples
        #

        stage = fo.SelectGroupSlices(media_type="image")
        view = dataset.add_stage(stage)

    Args:
        slices (None): a group slice or iterable of group slices to select.
            If neither argument is provided, a flattened list of all samples is
            returned
        media_type (None): a media type whose slice(s) to select
    """

    def __init__(
        self,
        slices=None,
        media_type=None,
        _allow_mixed=False,
        _force_mixed=False,
    ):
        self._slices = slices
        self._media_type = media_type
        self._allow_mixed = _allow_mixed
        self._force_mixed = _force_mixed

    @property
    def slices(self):
        """The group slice(s) to select."""
        return self._slices

    @property
    def media_type(self):
        """The media type whose slices to select."""
        return self._media_type

    def to_mongo(self, sample_collection):
        if isinstance(sample_collection, fod.Dataset) or (
            isinstance(sample_collection, fov.DatasetView)
            and len(sample_collection._stages) == 0
        ):
            return self._make_root_pipeline(sample_collection)

        return self._make_pipeline(sample_collection)

    def _make_root_pipeline(self, sample_collection):
        group_path = sample_collection.group_field + ".name"
        slices = self._get_slices(sample_collection)

        if etau.is_container(slices):
            return [{"$match": {"$expr": {"$in": ["$" + group_path, slices]}}}]

        if slices is not None:
            return [{"$match": {"$expr": {"$eq": ["$" + group_path, slices]}}}]

        return []

    def _make_pipeline(self, sample_collection):
        group_field = sample_collection.group_field
        id_field = group_field + "._id"
        name_field = group_field + ".name"

        slices = self._get_slices(sample_collection)
        expr = F(id_field) == "$$group_id"
        if isinstance(slices, list):
            expr &= F(name_field).is_in(slices)
        elif slices is not None:
            expr &= F(name_field) == slices

        pipeline = [
            {"$project": {group_field: True}},
            {
                "$lookup": {
                    "from": sample_collection._dataset._sample_collection_name,
                    "let": {"group_id": "$" + id_field},
                    "pipeline": [{"$match": {"$expr": expr.to_mongo()}}],
                    "as": "groups",
                }
            },
            {"$unwind": "$groups"},
            {"$replaceRoot": {"newRoot": "$groups"}},
        ]

        # @note(SelectGroupSlices)
        # Must re-apply field selection/exclusion after the $lookup
        if isinstance(sample_collection, fov.DatasetView):
            selected_fields, excluded_fields = _get_selected_excluded_fields(
                sample_collection
            )

            if selected_fields:
                stage = SelectFields(selected_fields, _allow_missing=True)
                pipeline.extend(stage.to_mongo(sample_collection))

            if excluded_fields:
                stage = ExcludeFields(excluded_fields, _allow_missing=True)
                pipeline.extend(stage.to_mongo(sample_collection))

        return pipeline

    def get_media_type(self, sample_collection):
        if self._force_mixed:
            return fom.MIXED

        group_media_types = sample_collection.group_media_types

        slices = self._get_slices(sample_collection)

        # All group slices
        if slices is None:
            media_types = set(group_media_types.values())

            if len(media_types) > 1:
                if self._allow_mixed:
                    return fom.MIXED

                raise ValueError(
                    "Cannot select all groups when dataset contains multiple "
                    "media types %s" % media_types
                )

            return next(iter(group_media_types.values()), None)

        # Multiple group slices
        if isinstance(slices, list):
            media_types = set()

            for _slice in slices:
                if _slice not in group_media_types:
                    raise ValueError(
                        "%s has no group slice '%s'"
                        % (type(sample_collection), _slice)
                    )

                media_types.add(group_media_types[_slice])

            if len(media_types) > 1:
                if self._allow_mixed:
                    return fom.MIXED

                raise ValueError(
                    "Cannot select slices %s with different media types %s"
                    % (slices, media_types)
                )

            return next(iter(media_types), None)

        # One group slice
        if slices not in group_media_types:
            raise ValueError(
                "%s has no group slice '%s'"
                % (type(sample_collection), slices)
            )

        return group_media_types[slices]

    def validate(self, sample_collection):
        if sample_collection.media_type != fom.GROUP:
            raise ValueError("%s has no groups" % type(sample_collection))

    def _get_slices(self, sample_collection):
        if self._media_type is not None:
            group_media_types = sample_collection.group_media_types
            slices = [
                slice_name
                for slice_name, media_type in group_media_types.items()
                if media_type == self._media_type
            ]
        else:
            slices = self._slices

        if not etau.is_container(slices):
            return slices

        slices = list(slices)

        if len(slices) == 1:
            return slices[0]

        return slices

    def _get_group_media_types(self, sample_collection):
        group_media_types = sample_collection.group_media_types
        slices = self._get_slices(sample_collection)

        if etau.is_container(slices):
            slices = set(slices)
        elif slices is not None:
            slices = {slices}
        else:
            slices = set(group_media_types.keys())

        return {
            slice_name: media_type
            for slice_name, media_type in group_media_types.items()
            if slice_name in slices or self._force_mixed
        }

    def _kwargs(self):
        return [
            ["slices", self._slices],
            ["media_type", self._media_type],
            ["_allow_mixed", self._allow_mixed],
            ["_force_mixed", self._force_mixed],
        ]

    @classmethod
    def _params(cls):
        return [
            {
                "name": "slices",
                "type": "NoneType|list<str>|str",
                "placeholder": "slices (default=None)",
                "default": "None",
            },
            {
                "name": "media_type",
                "type": "NoneType|str",
                "placeholder": "media_type (default=None)",
                "default": "None",
            },
            {
                "name": "_allow_mixed",
                "type": "NoneType|bool",
                "default": "None",
            },
            {
                "name": "_force_mixed",
                "type": "NoneType|bool",
                "default": "None",
            },
        ]

def load_config():
    """Loads the FiftyOne config.

    Returns:
        a :class:`FiftyOneConfig` instance
    """
    config_path = locate_config()
    if os.path.isfile(config_path):
        return FiftyOneConfig.from_json(config_path)

    return FiftyOneConfig()

class Take(ViewStage):
    """Randomly samples the given number of samples from a collection.

    Examples::

        import fiftyone as fo

        dataset = fo.Dataset()
        dataset.add_samples(
            [
                fo.Sample(
                    filepath="/path/to/image1.png",
                    ground_truth=fo.Classification(label="cat"),
                ),
                fo.Sample(
                    filepath="/path/to/image2.png",
                    ground_truth=fo.Classification(label="dog"),
                ),
                fo.Sample(
                    filepath="/path/to/image3.png",
                    ground_truth=fo.Classification(label="rabbit"),
                ),
                fo.Sample(
                    filepath="/path/to/image4.png",
                    ground_truth=None,
                ),
            ]
        )

        #
        # Take two random samples from the dataset
        #

        stage = fo.Take(2)
        view = dataset.add_stage(stage)

        #
        # Take two random samples from the dataset with a fixed seed
        #

        stage = fo.Take(2, seed=51)
        view = dataset.add_stage(stage)

    Args:
        size: the number of samples to return. If a non-positive number is
            provided, an empty view is returned
        seed (None): an optional random seed to use when selecting the samples
    """

    def __init__(self, size, seed=None, _randint=None):
        self._seed = seed
        self._size = size
        self._randint = _randint or _get_rng(seed).randint(int(1e7), int(1e10))

    @property
    def size(self):
        """The number of samples to return."""
        return self._size

    @property
    def seed(self):
        """The random seed to use, or ``None``."""
        return self._seed

    def to_mongo(self, _):
        if self._size <= 0:
            return [{"$match": {"_id": None}}]

        # @todo can we avoid creating a new field here?
        return [
            {
                "$addFields": {
                    "_rand_take": {"$mod": [self._randint, "$_rand"]}
                }
            },
            {"$sort": {"_rand_take": 1}},
            {"$limit": self._size},
            {"$project": {"_rand_take": False}},
        ]

    def _kwargs(self):
        return [
            ["size", self._size],
            ["seed", self._seed],
            ["_randint", self._randint],
        ]

    @classmethod
    def _params(cls):
        return [
            {"name": "size", "type": "int", "placeholder": "int"},
            {
                "name": "seed",
                "type": "NoneType|float",
                "default": "None",
                "placeholder": "seed (default=None)",
            },
            {"name": "_randint", "type": "NoneType|int", "default": "None"},
        ]

class Sample(_SampleMixin, Document, metaclass=SampleSingleton):
    """A sample in a :class:`fiftyone.core.dataset.Dataset`.

    Samples store all information associated with a particular piece of data in
    a dataset, including basic metadata about the data, one or more sets of
    labels (ground truth, user-provided, or FiftyOne-generated), and additional
    features associated with subsets of the data and/or label sets.

    .. note::

        :class:`Sample` instances that are **in datasets** are singletons,
        i.e.,  ``dataset[sample_id]`` will always return the same
        :class:`Sample` instance.

    Args:
        filepath: the path to the data on disk. The path is converted to an
            absolute path (if necessary) via
            :func:`fiftyone.core.storage.normalize_path`
        tags (None): a list of tags for the sample
        metadata (None): a :class:`fiftyone.core.metadata.Metadata` instance
        **kwargs: additional fields to dynamically set on the sample
    """

    _NO_DATASET_DOC_CLS = foo.NoDatasetSampleDocument

    def __init__(self, filepath, tags=None, metadata=None, **kwargs):
        super().__init__(
            filepath=filepath, tags=tags, metadata=metadata, **kwargs
        )

        if self.media_type == fomm.VIDEO:
            self._frames = fofr.Frames(self)
        else:
            self._frames = None

    def __repr__(self):
        kwargs = {}
        if self.media_type == fomm.VIDEO:
            kwargs["frames"] = self._frames

        return self._doc.fancy_repr(
            class_name=self.__class__.__name__, **kwargs
        )

    def _reload_backing_doc(self):
        if not self._in_db:
            return

        d = self._dataset._sample_collection.find_one({"_id": self._id})
        self._doc = self._dataset._sample_dict_to_doc(d)

    def reload(self, hard=False):
        """Reloads the sample from the database.

        Args:
            hard (False): whether to reload the sample's schema in addition to
                its field values. This is necessary if new fields may have been
                added to the dataset schema
        """
        if self.media_type == fomm.VIDEO:
            self.frames.reload(hard=hard)

        super().reload(hard=hard)

    def save(self):
        """Saves the sample to the database."""
        super().save()

    def _save(self, deferred=False):
        if not self._in_db:
            raise ValueError(
                "Cannot save a sample that has not been added to a dataset"
            )

        if self.media_type == fomm.VIDEO:
            frame_ops = self.frames._save(deferred=deferred)
        else:
            frame_ops = []

        sample_ops = super()._save(deferred=deferred)

        return sample_ops, frame_ops

    @classmethod
    def from_frame(cls, frame, filepath=None):
        """Creates a sample from the given frame.

        Args:
            frame: a :class:`fiftyone.core.frame.Frame`
            filepath (None): the path to the corresponding image frame on disk,
                if not available

        Returns:
            a :class:`Sample`
        """
        kwargs = {k: v for k, v in frame.iter_fields()}
        if filepath is not None:
            kwargs["filepath"] = filepath

        return cls(**kwargs)

    @classmethod
    def from_doc(cls, doc, dataset=None):
        """Creates a sample backed by the given document.

        Args:
            doc: a :class:`fiftyone.core.odm.sample.DatasetSampleDocument` or
                :class:`fiftyone.core.odm.sample.NoDatasetSampleDocument`
            dataset (None): the :class:`fiftyone.core.dataset.Dataset` that
                the sample belongs to

        Returns:
            a :class:`Sample`
        """
        sample = super().from_doc(doc, dataset=dataset)

        if sample.media_type == fomm.VIDEO:
            sample._frames = fofr.Frames(sample)

        return sample

    @classmethod
    def from_dict(cls, d):
        """Loads the sample from a JSON dictionary.

        The returned sample will not belong to a dataset.

        Returns:
            a :class:`Sample`
        """
        d.pop("_dataset_id", None)

        media_type = d.pop("_media_type", None)
        if media_type is None:
            media_type = fomm.get_media_type(d.get("filepath", ""))

        if media_type == fomm.VIDEO:
            frames = d.pop("frames", {})

        sample = super().from_dict(d)

        if sample.media_type == fomm.VIDEO:
            for fn, fd in frames.items():
                sample.frames[int(fn)] = fofr.Frame.from_dict(fd)

        return sample

